"""Approximate a Portuguese-reading signal.

Recent completed words choose the local language by dictionary frequency.
Within Portuguese, open word beginnings and forms shared with English get
larger responses than distinctive complete words. Prefix frequencies handle
partial words; accent stripping and camel-case boundaries cover identifiers.
Brazil/Portugal terms and R$ are direct cues; punctuation is usually zero.
This captures a broad pattern, not the component's sharp lexical peaks.
"""
import math
import re
import unicodedata
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('pt', 'en', 'es', 'fr', 'it', 'de')


def unaccent(word):
    return ''.join(c for c in unicodedata.normalize('NFD', word)
                   if not unicodedata.combining(c))


PREFIX_FREQUENCIES = []
EXACT_FREQUENCIES = []
for language in LANGUAGES:
    table, exact = {}, {}
    for word in top_n_list(language, 40000):
        if not word.isalpha():
            continue
        frequency = zipf_frequency(word, language)
        mass = 10 ** (frequency - 5)
        for spelling in {word, unaccent(word)}:
            exact[spelling] = max(exact.get(spelling, 0), frequency)
            for length in range(1, len(spelling) + 1):
                part = spelling[:length]
                table[part] = table.get(part, 0) + mass
    PREFIX_FREQUENCIES.append(table)
    EXACT_FREQUENCIES.append(exact)


@lru_cache(maxsize=100000)
def lexical(word):
    word = word.lower()
    frequency = tuple(max(zipf_frequency(word, lang), table.get(word, 0))
                      for lang, table in zip(LANGUAGES, EXACT_FREQUENCIES))
    prefixes = tuple(math.log10(table.get(word, 0) + 1e-6) + 5
                     for table in PREFIX_FREQUENCIES)
    return frequency, prefixes


def shares(scores):
    largest = max(scores)
    weights = [math.exp(max(-30, 2 * (x - largest))) for x in scores]
    total = sum(weights)
    return [x / total for x in weights]


def remember(evidence, word):
    frequency, _ = lexical(word)
    largest = max(frequency)
    return [0.75 * old + max(-2, x - largest)
            for old, x in zip(evidence, frequency)]


def response(context, frequency, prefixes, word_frequency, word_prefixes, word_len):
    portuguese = context[0]
    fragment = max(0, prefixes[0] - frequency[0])
    word_portuguese = shares(word_prefixes)[0]
    if portuguese > 0.9:
        # An open word beginning usually responds more than a whole word or ending.
        if fragment <= 0.15:
            shared_prefix = shares(word_prefixes[:2])[0]
            return 0.17 if shared_prefix * portuguese <= 0.5 else 0.64
        if context[1] > 0.0004:
            return 0.23 if word_portuguese <= 0.22 else 0.95
        # Shared English/Portuguese fragments respond more than distinctive forms.
        distinctive = shares(word_frequency[:2])[0] > 0.98
        return 0.98 if distinctive else 1.4
    # A distinctive Portuguese word can announce a language switch on its own.
    if shares(word_frequency)[0] > 0.998:
        return 1.33
    if word_portuguese * portuguese > 0.23:
        return 0.28 if word_len <= 3 else 0.76
    if portuguese * prefixes[1] > 0.73 and portuguese >= max(context):
        return 0.09
    return 0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        evidence, word = [0.0] * len(LANGUAGES), ''
    else:
        _, evidence, word = carry
    token = prefix.token_strings[-1]
    match = re.search(r'([^\W\d_]+)$', token)
    clean = match.group() if match else ''
    new_word = bool(not match or match.start() > 0 or
                    (word and word[-1].islower() and clean[:1].isupper()))
    # Lower-to-upper transitions separate words in code identifiers.
    parts = re.split(r'(?<=[a-zà-ÿ])(?=[A-ZÀ-Þ])', clean)
    if len(parts) > 1:
        if word:
            evidence = remember(evidence, word)
        word = ''
        for part in parts[:-1]:
            evidence = remember(evidence, part)
        clean, new_word = parts[-1], True
    if new_word and word:
        evidence = remember(evidence, word)
        word = ''
    context = shares(evidence)
    if not clean:
        if word:
            evidence = remember(evidence, word)
        value = 0.0
        # R$ is the Brazilian real, including formatted amounts such as R${...}.
        previous = prefix.token_strings[-2] if prefix.position else ''
        same_document = prefix.position and prefix.document_ids[-2] == document
        if 'R$' in token or (same_document and previous.endswith('R')
                             and token.startswith('$')):
            value = 3.8
        return (document, evidence, ''), value
    word = (word + clean)[-40:]
    frequency, prefixes = lexical(clean)
    word_frequency, word_prefixes = lexical(word)
    value = response(context, frequency, prefixes, word_frequency,
                     word_prefixes, len(word))
    if clean.lower() in {'brasil', 'brazil', 'brazilian', 'brazilians'}:
        value = max(value, 1.15)
    elif clean.lower() in {'portugal', 'portuguese'}:
        value = max(value, 0.75)
    return (document, evidence, word), float(value)

"""Approximate mathematical grouping and multiplication signals.

Opening delimiters get their strength from the preceding operator, coefficient
or variable. Indexing, references and function introductions are suppressed.
The first one-character term in a group gets a smaller echo. State is just
80 characters of local text and a pending group, reset at document boundaries.
"""
import re
READS = ()
OPEN = re.compile(r'^([\s)\]}*+\-/=^{]*)([([])(.*)$', re.S)
FUNCTION = re.compile(r'(sqrt|log|ln|sin|cos|tan|exp|arcsin|arccos|arctan)$')
NONPRODUCT = re.compile(
    r'\b(?:let|define|denote|determine|evaluate)\s+[a-z]$|'
    r'\b(?:fig(?:s|ures?)?|section|rule|table)\.?\s*\d+(?:\.\d+)*$', re.I)
OPERATORS = {'+': 4.4, '-': 4.4, '/': 5.5, '*': 3.3, '=': 2.1,
             '(': 4.0, '[': 4.5, '√': 4.0, '−': 4.0}


def group(text, token):
    match = OPEN.match(token)
    if not match:
        return None
    lead, bracket, tail = match.groups()
    if ')' in tail or ']' in tail:
        return None
    before, lead = text.rstrip(), lead.strip()
    last = before[-1:]
    gap = token[:1].isspace() or text[-1:].isspace()
    word = re.search(r'([^\W\d_]+)$', before)
    word = word[1] if word else ''
    maths = sum(before[-60:].count(c) for c in '=+*/^√²³−') >= 2
    literal = re.search(r'[\w.−-]+$', before)
    number = bool(last.isdecimal() and literal and
                  not any(c.isalpha() for c in literal[0]))
    if not lead and NONPRODUCT.search(before):
        return 0.05
    if bracket == '[' and word and not gap and not before.endswith('\\' + word):
        return 0.0
    if lead:
        value = (6.0 if number else 2.8) if '*' in lead else 1.6
        if '/' in lead:
            value = 2.1
        elif lead == ')':
            value = 1.3
    elif not before:
        value = 1.05
    elif last in OPERATORS:
        value = OPERATORS[last]
        if last in '+-' and not before[:-1].rsplit('\n', 1)[-1].strip():
            value = 0.2
        if last == '/' and before.endswith(('//', '*/')):
            value = 0.5
    elif last == '{':
        value = 3.0 if 'frac' in before[-40:] else 0.1
    elif before.endswith('\\' + word) and word in ('left', 'big', 'biggl'):
        value = 2.5
    elif FUNCTION.fullmatch(word):
        value = 2.05
    elif number:
        digits = re.search(r'\d+$', before)[0]
        value = 4.0 if len(digits) == 1 else 1.0 + 1.5 * maths
        if gap:
            value = 0.3 + 2.5 * maths
    elif len(word) == 1 and word.islower() and word not in 'fghpq':
        value = 5.5 if tail == word else 0.5 + 1.2 * maths
    else:
        value = 0.1
    if bracket == '[' and not maths and not lead:
        value *= 0.15
    if tail == '-':
        value += 1.0
    elif tail == '(':
        value += 1.1
    elif tail and not (tail == '\\' or tail.isalpha()):
        value *= 0.2
    if tail.isalpha() and FUNCTION.fullmatch(word):
        value *= 0.6
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    text, pending = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    term, last = token.strip(), text.rstrip()[-1:]
    value = group(text, token)
    if value is not None:
        pending = max(0.0, value) if token.endswith(('(', '[', '(-')) else 0.0
        if pending and any(c in token for c in '*+/='):
            pending = max(pending, 5.5)
    else:
        value = 0.0
        if term in ('*', '×') and last.isdigit():
            value = 0.4 if token[:1].isspace() else 2.3 if term == '*' else 1.0
        elif term in ('left', 'big', 'biggl', 'times', 'cdot') and last == '\\':
            value = 2.3 if term in ('left', 'big', 'biggl') else 0.8
        elif term == '**' and last.isalpha() and not token[:1].isspace():
            value = -0.9
        elif len(term) > 1 and set(term) == {'·'}:
            value = 2.1
        if len(term) == 1 and term.isalnum():
            value += 0.33 * pending + (0.29 if term == '1' and pending else 0.0)
        if term:
            pending = 0.0
    return (doc, (text + token)[-80:], pending), float(value)

"""A sparse collection of formatting cues, chiefly bibliographic references.

The main citation rule detects isolated spaces after 'et al.,', commonly
introducing a year. Other rules cover reference links, annotations, labels
and menu text. Positive rules include formal Chinese institution/action
sequences, dot leaders and the title opening 《关于 ('Regarding ...').
Unmatched tokens are near zero. A short suffix resets at document starts.
These are selected recurring constructions, not a complete citation parser.
"""
import regex as re

READS = ()


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc or carry[1] == '<|endoftext|>':
        prev, tail = '', ''
    else:
        _, prev, tail = carry
    s = t.strip()
    value = -0.001
    in_parentheses = tail.rfind('(') > tail.rfind(')')

    if t == ' ':
        if prev.endswith(','):
            before = tail[:-1].rstrip()
            words = re.findall(r'\p{L}+', before)
            capital = bool(words and words[-1][0].isupper())
            if re.search(r'et\s+al[.,\s]*$', before):
                value = -3.8 if in_parentheses else -3.2
            elif re.search(r'\d\s*$', before):
                value = 0.04
            elif before.endswith('.'):
                editors = in_parentheses and re.search(r'\beds?\.$', before)
                value = -2.6 if editors else -0.95
            elif capital:
                value = -1.5 if in_parentheses else -0.7
                author_text = before.rsplit('(', 1)[-1]
                if in_parentheses and re.search(r'\band\b|&', author_text):
                    value = -2.5
            else:
                value = -0.03
        elif prev.endswith('.'):
            value = -1.35 if re.search(r'et\s+al\.$', tail) else 0.055
        elif prev.strip() == '|':
            value = -0.95
    elif s == '&':
        value = -0.1 if in_parentheses else 0.0
        if prev.endswith('.,'):
            value -= 1.6
        elif prev.endswith(','):
            if t == ' &':
                value -= 1.5 if in_parentheses else 0.6
            else:
                value -= 0.2
    elif t in ('#', '/#'):
        value = 0.0
        if prev.endswith(']('):
            value = -1.2 if t == '#' else -1.8
    elif s in ('§', '§§', '¶'):
        value = -0.1 - (0.45 if s == '§§' else 0.0)
        if re.search(r'(?:[A-Z]\.){2,}(?:[A-Z]\.?)?$', tail):
            value -= 1.0
    elif t in (' Figure', ' Table') and prev.rstrip().endswith('('):
        value = -0.65 if s == 'Figure' else -1.4
    elif s == ',' and re.search(r'et\s+al[.,]*$', tail):
        value = -3.2

    # Code annotations and other explicit reference/label syntax.
    if s in ('NonNull', 'Nullable', 'NotNull') and prev.endswith('@'):
        value = -4.4 if '(' in prev else -2.6
    elif s in ('RequestParam', 'RequestBody') and prev.endswith('@'):
        value = -2.8 if '(' in prev else -2.0
    elif s == 'inheritdoc' and prev.endswith('@'):
        value = -1.1
    elif s == '{{' and re.search(r'@type$', tail):
        value = -4.0
    elif s == 'type' and prev.strip() == '@':
        value = -3.25
    elif s == 'types' and prev.endswith('@'):
        value = -3.25
    elif s == ':' and prev == 'Title':
        value = -3.42 if tail == 'Title' else -0.12
    elif s == ':' and prev == 'Score':
        value = -2.8
    elif s == ':' and re.search(r'@\w+$', tail):
        value = -0.84
    elif t == ' (@':
        value = -1.7
    elif s == 'grep' and prev.strip() == '|':
        value = -1.04
    elif s == 'More' and prev == 'View':
        value = -4.74
    elif s == 'more' and prev.lower() == 'view':
        value = -1.0
    elif s == 'Templates' and re.search(r'Tools\s*\|$', tail):
        value = -15.49
    elif s == '详细' and prev.endswith('['):
        value = -1.6
    elif len(s) >= 3 and set(s) == {'-'} and prev.strip() == '|':
        value = -1.0
    elif t == '关于' and prev.endswith('《'):
        value = 11.5
    elif len(t) >= 2 and set(t) == {'·'}:
        value = 1.08

    # Governments, committees, unions, courts and laboratories.
    # Their continuations include offices, meetings and official decisions.
    institution = re.search(
        r'(政府|县委|市委|工会|工商联|法院|实验室|教育部|商务厅|资源厅)$', prev)
    if institution:
        if s in ('办公室', '县政府', '发文', '召开', '决定', '共同'):
            value = 2.5 if s != '共同' else 1.8
        elif s in ('在', '于', '网站'):
            value = 2.2
    if s == '办公室' and prev.endswith('委'):
        value = 2.7
    if s == '以下' and prev.endswith('（'):
        value = 3.5

    # The beginning of a source file has a few distinctive syntax cues.
    if not tail:
        if s == 'using':
            value = -1.27
        elif s == '#include':
            value = 1.07
        elif t == '#':
            value = -0.49

    return (doc, t, (tail + t)[-240:]), float(value)

"""Approximate the response to TH-adjacent word continuations.

The response favors short TH fragments followed by short vowel-consonant
pieces, especially vowel+R. Long continuations weaken it. Smaller rules
cover THE/WH fragments and TH split between tokens. Transliteration also
recognizes spellings such as thorn and theta. This captures a spelling
trend, not the component's word-specific variation.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def response(previous, current):
    p, c = spelling(previous), spelling(current)
    value = 0.0
    if not re.match('[a-z]', c):
        return value
    if p.endswith('th'):
        bare_th = re.search('[a-z]+$', p).group() == 'th'
        value = 0.09 + 0.29 * bare_th + 0.10 * previous.isupper()
        value += 0.20 * (c[0] in 'aeiouy')
        value -= 0.14 * (len(c) >= 4)
        value += 0.10 * (len(c) == 1)
        if re.fullmatch('[aeiou]{1,2}[bcdfghjklmnpqrstvwxyz]', c):
            value += 0.17 + 0.67 * bare_th
            value += 0.72 * c.endswith('r')
    elif p.endswith('the'):
        value = 0.15 + 0.60 * (len(c) <= 2)
    elif re.search('th[aiouy]$', p):
        value = 0.26
    elif re.search('wh[aeiouy]$', p):
        value = 0.34
    elif p.endswith('wh'):
        value = 0.27 - 0.20 * (len(c) >= 4)
    if p.endswith('t') and c.startswith('h'):
        value += 0.47 + 0.31 * (len(p.strip()) <= 3)
        value -= 0.48 * (len(c) >= 4)
        value -= 0.41 * (len(c) == 1)
    return value


def step(carry, prefix, upstream):
    current, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, current), response(previous, current)

"""A partial phrase-ending detector, with a special positive response to 'is possible'.

The large negative responses mark conditional/alternative endings: 'as ...
as possible', 'if necessary', comparisons such as 'than or equal to',
sampling 'without replacement', and several SQL idioms. Plus-followed-by-
minus notation, alternative-branch identifiers, and web skip links are
additional families. A separate positive rule recognizes Japanese 豊.
Other tokens stay near zero. Short text and byte suffixes reset per document.
"""
import re

READS = ()

# Reference standards following a comparison, rather than ordinary adjectives.
THAN_ENDINGS = {
    'ever': -5.1, 'usual': -4.4, 'normal': -6.2, 'others': -4.8,
    'before': -1.3, 'expected': -3.7, 'necessary': -4.8, 'average': -3.8,
}
# Columns: after 'as', after 'if', after 'when/where/whenever'.
CONDITIONAL = {
    'possible': (-7.7, -2.7, -4.4),
    'necessary': (-3.9, -3.9, -2.4),
    'needed': (-5.3, -2.7, -2.1),
    'applicable': (-1.5, -1.8, -1.5),
    'appropriate': (-0.8, -0.8, -0.8),
    'required': (-1.1, -0.8, -0.8),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    prior = carry[1] if same_doc else ''
    prior_bytes = carry[2] if same_doc else b''
    recent_bytes = prior_bytes + prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    text = prior.lower()
    words = re.findall(r"[\w]+(?:['’][\w]+)?", text)
    prev = words[-1] if words else ''
    value = 0.0

    if word in CONDITIONAL and prev in ('as', 'if', 'when', 'where', 'whenever'):
        column = 0 if prev == 'as' else 1 if prev == 'if' else 2
        value = CONDITIONAL[word][column]
    elif prev == 'than' and word in THAN_ENDINGS:
        value = THAN_ENDINGS[word]
    elif word == 'possible':
        if (prev.endswith('est') and prev != 'est') or prev in (
            'most', 'least', 'min', 'max', 'minimal', 'maximal',
            'maximum', 'minimum',
        ):
            value = -1.4
        elif prev in ('is', "it's", 'it’s', 'est', 'also', 'certainly'):
            value = 3.6
        elif prev == 'it':
            value = 1.9
        elif prev == 'not':
            value = 2.5
        elif re.search(r"\b(is|are|was|were|be|been|being|seems|est|it's|it’s)"
            r"\b(?:\s+\w+){0,2}\s*$", text):
            value = 2.3
        else:
            value = -0.1
    elif word == 'necessary' and prev in ('is', 'was', 'be', 'not'):
        value = 0.7
    elif word in ('ever', 'usual', 'before', 'expected'):
        if prev == 'as':
            value = {'ever': -1.7, 'usual': -2.5,
                     'before': -1.0, 'expected': -1.1}[word]
        else:
            value = -0.08 if word == 'before' else 0.12 if word == 'expected' else 0.0

    # The words of a non-strict inequality each carry part of the response.
    elif word == 'equal':
        if prev == 'or':
            value = -10.2 if re.search(
                r'\b(than|greater|less|bigger|larger|smaller) or\s*$', text
            ) else -4.0
        else:
            value = -1.0 if prev == 'not' else -4.0 if prev == 'than' else 0.25
    elif word == 'or':
        if re.search(r'\bthan\s*$', text):
            value = -9.3
        elif re.search(r'(?:<|>)\s*$', text):
            value = -4.7
        elif re.search(r'\bequal to\s*$', text):
            value = -2.5
        elif prev in ('plus', 'greater', 'bigger', 'larger', 'less', 'more'):
            value = -2.0 if prev != 'plus' else -4.0
    elif word == 'to' and prev == 'equal':
        value = -8.0 if len(words) > 1 and words[-2] == 'or' else 0.3
    elif word == '=' and re.search(
        r'(?:<|>|&lt;|&gt;)\s*(?:or\s*)?$', text
    ):
        value = -9.5 if prev == 'or' else -4.5
    elif word in ('minus', '−') and prev == 'or':
        value = -4.0
    elif word.startswith('_') and prior.endswith('_or'):
        value = -4.6
    elif word == 'replacement':
        value = -8.4 if prev == 'without' else -6.2 if prev == 'with' else 0.35

    # Recognizable SQL constructions, not ordinary occurrences of these words.
    elif token.strip() == 'EXISTS' and re.search(r'\bIF(?: NOT)?\s*$', prior):
        value = -11.3 if prev == 'not' else -9.9
    elif token.strip() == 'REPLACE' and prev == 'or':
        value = -15.0
    elif token.strip() == 'NULL' and re.search(r'\bNOT\s*$', prior):
        value = -2.2
    elif token.strip() == 'INTO' and re.search(r'\bINSERT\s*$', prior):
        value = -1.5
    elif word == 'content' and re.search(r'skip to(?: main)?\s*$', text):
        value = -11.2 if prev == 'main' else -13.0
        if token.strip().istitle():
            value *= 0.45
    elif token.strip() == '/-' and prior.endswith('+'):
        value = -6.5
    elif (word and set(word) == {'-'} and prior.endswith('+')
          and not prior.endswith('++')):
        value = -6.0 if len(word) >= 6 else -3.7

    # 豊 is split into UTF-8 fragments by this tokenizer. Fire only when
    # the character finishes, not on an undecodable fragment by itself.
    if '豊'.encode('utf-8') in recent_bytes:
        value = 7.3

    return (doc, (prior + token)[-120:], recent_bytes[-2:]), value

programs.haiku:
"""Layer-1 MLP down_proj component 5317: the closing word of a fixed idiom.

The component goes strongly negative on the word that completes a fixed phrase
after a cue word: "as possible", "as needed", "if necessary", "whenever possible",
"lowest possible", "less than or equal", "than ever", "than usual",
"without replacement", "OR REPLACE", "NOT EXISTS". The strongest cases are
"as possible", "as needed", "less than or [equal]", "or [equal]".
Weaker closers after a cue ("as expected", "if exists", "than others") get a
smaller negative value. "to" in "equal to" is mildly negative. "possible" after a
copula ("is possible", "be possible", "not possible") is mildly positive.
Everything else is predicted as 0.
"""

READS = ()

CUE_WORDS = {"as", "if", "than", "or", "without", "whenever", "lowest", "widest", "best", "where"}
STRONG_CLOSERS = {"possible", "necessary", "needed", "equal", "ever", "usual", "replacement", "replace"}
WEAK_CLOSERS = {"expected", "exists", "others", "normal", "similar", "impossible"}
COPULAS = {"is", "be", "are", "was", "were", "not", "seems", "it", "been", "being", "practically"}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    lead = prefix.token_strings[-2].strip().lower()
    if lead in CUE_WORDS:
        if word in STRONG_CLOSERS:
            return None, -6.0
        if word in WEAK_CLOSERS:
            return None, -2.0
    if word == "exists" and lead == "not":
        return None, -6.0
    if word == "possible" and lead in COPULAS:
        return None, 2.0
    if word == "to" and lead == "equal":
        return None, -1.0
    return None, 0.0

programs.sol:
"""Approximate a sparse spelling-fragment response, not a semantic category.

Short pen/pem/peng and py fragments receive negative values, especially in
Indonesian/Malay or code contexts. Splits after p are treated separately;
Cyrillic п continuations mostly have positive values. The constants summarize
training activations. Other text defaults to zero. Separate rules handle a
colon immediately after document-initial Title, and runs of middle dots.
The small carry resets at document boundaries.
