import re

READS = ()

# Common Indonesian/Malay function words identify the peN- nominal prefix.
MALAY = frozenset('yang dan untuk dengan dalam pada dari ini itu tidak '
                  'akan dapat sebagai adalah juga atau oleh kepada'.split())


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, count, malay = '', 0, 0.0
    else:
        _, prev, count, malay = carry
    w = s.lstrip(' \t\n./_-(\"\'&').lower()
    malay *= 0.94
    if s.startswith(' ') and w in MALAY:
        malay += 1.0
    value = 0.0

    if count == 1 and prev == 'Title' and s == ':':
        value = -19.37
    elif len(s) > 1 and prev == s and set(s) == {'·'}:
        value = -1.18
    elif w in ('peng', 'peny', 'pem', 'penc', 'pemb'):
        value = -8.0 if w != 'pemb' else -5.0
        if w == 'pemb' and s.lstrip()[:1].isupper():
            value = -2.3
    elif w in ('pen', 'pend', 'pent', 'penn', 'penny', 'pe', 'pel', 'pew'):
        if malay > 0.6 and w in ('pen', 'pend', 'pent', 'pe', 'pel'):
