                     'pe': -2.5, 'pel': -3.5}[w]
        elif w == 'pen':
            value = -2.7 if s.lstrip()[:1].isupper() else -1.0
        else:
            value = -0.7 if w in ('penn', 'penny', 'pel') else -1.3
            if w == 'pe':
                value = -0.3 if s[:1].isspace() else 0.0
    elif w in ('open', 'opens', 'openh', 'opener'):
        value = -1.0 if s.lstrip()[:1].isupper() else -0.45
        if s.startswith(('.', '/', '-')) or w in ('opens', 'openh'):
            value = -2.0
        if prev.lower().strip() in ('org', 'lib'):
            value = -5.5
    elif re.fullmatch('py[a-z]?', w):
        value = -1.5 if s[:1].isspace() else -0.8
        if s.startswith('.'):
            value = 0.0
        if prev.strip() in ('import', 'from', 'return', 'install', ':', '='):
            value -= 0.8

