                    or w in ('entr', 'ense', 'enny', 'ener', 'enger')):
                value = -3.2
                if w == 'en':
                    value = -4.5 if prev.rstrip()[-1:].isupper() else -3.0
                if p.endswith('pp'):
                    value = -1.8
                elif p.endswith('op'):
                    value = -7.0
                    if w.startswith(('entr', 'ense')):
                        value = -11.0
                    elif w.startswith('ent') and '/' in p:
                        value = -17.0
                    elif w == 'ener':  # The ordinary word opener.
                        value = -2.0
                if w == 'ens':  # Plural/inflection-like ending.
                    value = -0.2
            elif w.startswith('em'):
                value = -6.5 if w in ('em', 'emb') else -2.8
            elif w.startswith('y') and len(w) <= 3:
                value = -1.0 if w in ('yl', 'yr') else -2.5
                if w == 'yp':
                    value = -4.5
                if w.startswith('yst'):
                    value = -7.0
            elif w.startswith('e'):
                value = -0.2
            elif w == 'open' and p.strip() == 'p':
                value = -6.0
            elif w in ('m', 'am', 'ng'):
                value = -1.2
            elif w.startswith(('iz', 'on')):
                value = 1.4
        elif p.endswith('py'):
            value = -4.5 if w in ('b', 'd', 'l') else -0.1
            if w in ('x', 't'):
                value = -3.2
        elif p.endswith('pry') and w == 'm':
            value = -1.0
        elif p.endswith('п'):
            if w.startswith('лю'):
                value = 5.9
            elif w.startswith('ен'):
                value = -2.8 if p.strip() == 'п' else -1.0
            elif w.startswith('ят'):
                value = 3.2 if p.endswith('преп') else 0.3
            elif w.startswith('есс'):
                value = 4.5
            elif w in ('ла', 'ы'):
                value = 2.4 if p.strip() == 'п' else 0.1
            else:
                value = 0.5 if p.strip() == 'п' else 0.1

    return (doc, s, count + 1, malay), float(value)

programs.haiku:
"""Layer 1 MLP output, component 5319: a spelling detector for word starts that spell
p-e-n-g, p-e-m, p-e-n-y, o-p-e-n or p-y, as they are typed one token at a time.

The program follows the word being typed (the letters since the last non-letter, carried
across tokens) and fires on the token at which the word first starts with one of these:
- "peng", "pem", "peny" (Indonesian prefixes: pengetahuan, pemerintah, penyebab): strongly negative;
- "open" finished from a fragment, e.g. "op" then "en...", as in "opentelemetry": strongly negative;
- "open" as a whole word: weakly negative;
- "pen" or "py" starting a word: mildly negative, more so when the token continues a fragment
  (e.g. "Code" + "Pen", "red" + "pen");
- "плю" (Russian "plu-", as in "плюс"): positive.
A colon that directly follows a document's first token "Title" is strongly negative.
Everything else predicts 0. Whole English words such as "pension" or "pending" are near zero,
which this rule does not check for, so their small false alarms cost some variance.
"""

READS = ()


def starts(word, old, stem):
    """True when `word` has just come to start with `stem`, which the word before did not."""
    return word.startswith(stem) and not old.startswith(stem)


def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        old, index, previous = "", 0, ""
    else:
        old, index, previous = carry[0], carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    # the trailing letters of this token, lowercased; joined to the word so far if the token is all letters
    cut = len(token)
    while cut > 0 and token[cut - 1].isalpha():
        cut -= 1
    word = (old if cut == 0 else "") + token[cut:].lower()
    fragment = cut == 0 and old != ""  # the token continues the word typed so far

    value = 0.0
    if index == 1 and previous == "Title" and token == ":":
        value = -19.4
    elif starts(word, old, "peng") or starts(word, old, "pem") or starts(word, old, "peny"):
        value = -7.0
    elif starts(word, old, "open"):
        value = -11.0 if fragment else -0.6
    elif starts(word, old, "плю"):
        value = 3.0
    elif starts(word, old, "pen"):
        value = -2.4 if fragment else -0.9
    elif starts(word, old, "py"):
        value = -2.3 if fragment else -0.3
    return (word, index, token), value

programs.sol:
"""Approximate a word-start 'na' detector, chiefly in Slavic languages.

Spelling, token boundaries, capitalization and recent language distinguish its
large negative responses from weak word-ending responses. Portuguese 'na' is
positive instead. Common Russian governing words modulate the response; German
'auf' and Greek nu + alpha are weaker triggers. Most tokens predict zero.
A separate small rule covers long runs of middle dots.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LATIN_LANGUAGES = (
    'en', 'pt', 'pl', 'cs', 'sk', 'sh', 'sl',
    'es', 'it', 'hu', 'tr', 'de', 'lt',
)
SLAVIC_LATIN = ('pl', 'cs', 'sk', 'sh', 'sl')
# Pieces completing word-initial Cyrillic н + а, with token-specific strengths.
NA_COMPLETIONS = {
    'ав': -11.1,
    'ап': -6.9,
    'ар': -10.0,
    'аст': -8.1,
}


@lru_cache(maxsize=32000)
def frequency(word, lang):
    return zipf_frequency(word, lang)


def language(text, choices=LATIN_LANGUAGES):
    words = [w for w in re.findall(r'(?<!\w)[^\W\d_]+(?!\w)', text.lower())
             if len(w) > 1][-16:]
    if not words:
        return ''
    scores = {lang: sum(frequency(w, lang) for w in words) for lang in choices}
    best = max(scores, key=scores.get)
    if best in SLAVIC_LATIN:
        baseline = max(scores.get('en', 0), scores.get('pt', 0))
        if scores[best] - baseline < 0.5 * len(words):
            return ''
    return best


def response(text, previous, token):
    s = token.lstrip()
    low = s.lower()
    boundary = token != s or not text or not (
        text[-1].isalpha() or unicodedata.category(text[-1]).startswith('M'))
    if token and set(token) == {'·'} and text.endswith('·' * 8):
        return -1.34
    if s in ('NA', 'НА'):
        return -0.4
    if low in ('na', 'на') and not text:
        return -6.3
    if low == 'на':
        if not boundary:
            return -0.5
        if language(text, ('ru', 'bg', 'uk')) == 'bg':
            return -6.8
        if s[0].isupper():
            return -14.2 if token != s else -16.0
        words = re.findall(r'[^\W\d_]+', text.lower())
        last = words[-1] if words else ''
        if last.startswith('вли'):  # influence
            return -6.8
        if last.startswith(('вниман', 'смотр', 'несмотр')):  # attention/look/despite
            return -8.3
        if last.startswith(('ответ', 'отвеч', 'право', 'права', 'вопрос')):
            return -15.2  # answer, right, question
        return -11.6
    if boundary and low.startswith('на') and 2 < len(low) <= 6:
        return -2.2 if len(low) == 3 else -0.35
    if token == s and low.startswith('а') and text.lower().endswith('н'):
        if not re.search(r'\bн$', text.lower()):
            return -0.4
        if len(low) == 1:
            return -13.5 if s.isupper() else -4.0
        return NA_COMPLETIONS.get(low, -3.8 if len(low) == 2 else -0.3)
    if low == 'na':
        if not boundary:
            return -0.15
        lang = language(text)
        if lang == 'pl':
            return -10.8
        if lang in ('cs', 'sk'):
            return -8.8
        if lang in ('sh', 'sl'):
            return -5.0
        return 0.7 if lang == 'pt' else -2.0
    if boundary and low.startswith('na') and len(low) == 3:
        if language(text) in SLAVIC_LATIN:
            return -2.5
    if s and token == s and re.search(r'\bn$', text.lower()):
        if unicodedata.normalize('NFD', low[0])[0] == 'a':
            if language(text) in SLAVIC_LATIN:
                return -5.1 if len(low) == 1 else -2.5
    if low == 'α' and re.search(r'\bν$', text.lower()):
        return -1.4
    if low == 'auf':
        return -4.0 if s[0].isupper() else -3.25
    if low.endswith('auf'):
        return -1.0
    if low == 'uf' and previous.lower().endswith(('a', 'ä')):
        return -6.5 if previous.strip().lower() == 'a' else -2.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    value = response(text, previous, token)
    return (doc, (text + token)[-180:], token), value

"""Recognize Chinese attained-result complements, especially 到 after a verb.

Seeing, finding, learning, feeling and acquiring something give a negative
response. A separately tokenized complement is stronger than a whole-word
one. Locative 到 (going or sending *to* somewhere) is not an attained result.
English learn/look + to and Vietnamese attainment phrases are also matched.
Document-initial Title: and 12 have separate, positive format responses.
Unmatched tokens receive zero; these rules do not explain the full component.
"""

import codecs

READS = ()

# Selected verb roots: see/hear/feel/learn, find/get/take/buy, and other
# actions whose 到 complement marks an achieved result rather than a location.
PERCEIVE = (
    '看', '听', '聽', '见', '見', '查', '学', '學', '感觉', '感覺',
    '感受', '体会', '體會', '理解', '了解', '瞭解', '意识', '意識',
)
ACQUIRE = (
    '找', '得', '取', '拿', '抢', '搶', '抓', '买', '買',
    '购买', '購買', '收', '搜救', '吃',
)
OTHER_RESULT = (
    '遇', '碰', '接', '帮', '幫', '帮助', '幫助', '用', '问', '問',
    '邀请', '邀請', '匹配', '影响', '影響', '伤害', '傷害',
    '关注', '召唤', '召喚',
    '选', '選', '选择', '選擇', '谈', '談', '办', '辦', '咬',
    '梦', '夢', '顶', '頂', '磨', '定位', '拉', '教', '追', '渗', '滲',
)


def predict(token, previous, before_previous, position):
    t = token.strip()
    p = previous.strip()
    if position == 1 and p == 'Title' and t == ':':
        return 6.27
    if position == 1 and p == '1' and t == '2':
        return 3.59
    if t == 'to':
        word = p.lower()
        if word in {'learn', 'learns', 'learned', 'learnt', 'learning'}:
            return 2.3
        if word in {'look', 'looks', 'looked', 'looking'}:
            return 0.8
        if word in {'know', 'knows', 'knew', 'seem', 'seems',
                    'afford', 'refused'}:
            return 0.6
    if t == 'được':
        return -1.3
    if t == 'thấy':
        return -1.1
    if t in {'cách', 'hiểu'} and p.lower() == 'tìm':
        return 1.5
    if t in {'到', '到了', '不到'}:
        stem = p
        if stem in {'的', '得'}:
            stem = before_previous.strip()
        compound = before_previous.strip() + stem
        if compound in PERCEIVE + ACQUIRE + OTHER_RESULT:
            stem = compound
        if stem in PERCEIVE + ACQUIRE:
            return -6.0
        if stem in OTHER_RESULT:
            return -2.8
        return 0.0
    word = t[:-1] if t.endswith('了') else t
    if word.endswith('到'):
        stem = word[:-1]
        if stem.endswith('不'):
            stem = stem[:-1]
        if stem.endswith(('感受', '收', '吃', '见', '見', '拿')):
            return -2.6
        if stem.endswith(('看', '找', '感', '体会', '體會')):
            return -1.9
        if stem.endswith(('遇', '碰', '得', '听', '聽', '了解', '瞭解',
                          '意识', '意識', '受')):
            return -1.4
        if stem.endswith(('想', '考虑', '考慮', '涉及', '注意', '提')):
            return -0.6
    if t == '得' and p in {'取', '贏', '赢', '征', '徵', '習', '习'}:
        return -2.0
    if t in {'懂', '清'} and p in {'看', '听', '聽', '读', '讀', '秒', '撇'}:
        return -1.2
    if t in {'见', '見'} and p in {'看', '遇', '求', '惊', '驚', '仅', '僅'}:
        return -1.1
    if t in {'取', '获', '獲'} and p in {
        '读', '讀', '领', '領', '收', '缴', '繳'
    }:
        return -1.2
    if t in {'看见', '看見', '可见', '可見'}:
        return -1.1
    if t in {'获得', '獲得', '获得了', '獲得了', '发现', '發現'}:
        return -0.6
    if t in {'找', '来找', '來找', '去找', '尋', '寻'}:
        return 0.7
    if t in {'有机会', '有機會'}:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, before_previous, position, pending = '', '', 0, b''
    else:
        _, previous, before_previous, position, pending = carry
    # Carry unfinished UTF-8 bytes until their character is complete.
    data = pending + prefix.token_bytes[-1]
    token, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    value = predict(token, previous, before_previous, position)
    if token:
        before_previous, previous = previous, token
    state = document, previous, before_previous, position + 1, pending
    return state, value

"""Partial approximation: chat boundaries and the digit pairs 30 and 31.

On the blank line after an empty thought, predict from document length
and the number of completed messages. A nonempty thought has a separate
baseline. On 30/31, respond negatively to the second digit: more strongly
after English month names, and more weakly inside longer numbers. A
colon strengthens the 30 response. Other tokens receive small baselines.
Most token-specific variation is not modeled. Reset state per document.
"""
import math
import re

READS = ()
MONTH = re.compile(
    r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|June?|'
    r'July?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|'
    r'Dec(?:ember)?)\.?\s*$', re.I)


def answer_gap(ends, empty, position):
    if not empty:
        return -0.05
    # Longer documents and at least two completed messages shift it up.
    return -0.0443 + 0.0097 * math.log1p(position) + 0.0225 * (ends >= 2)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, digits, before, tail = '', 0, '', ''
        ends, thought_length, empty, position = 0, -1, False, 0
    else:
        (_, previous, digits, before, tail, ends,
         thought_length, empty, position) = carry
        position += 1
    token = prefix.token_strings[-1]
    value = -0.14 if first else 0.001
    if token == '<|im_start|>':
        value = -0.30 if first else -0.025
    elif token == '<think>':
        value = -0.034
    elif token == '</think>':
        value = -0.032
    elif token == '\n\n' and previous == '</think>':
        value = answer_gap(ends, empty, position)
    elif token == '\n\n' and previous == '<think>':
        value = -0.092
    elif previous == '3' and token in ('0', '1'):
        if digits == 1:
            value = -0.46 if token == '0' else -0.25
            if MONTH.search(before):
                value = -1.05 if token == '0' else -0.83
            elif before.endswith(':') and token == '0':
                value = -0.58
        else:
            value = -0.19 if token == '0' else -0.065
    if len(token) == 1 and token in '0123456789':
        if not digits:
            before = tail
        digits += 1
    else:
        digits = 0
    if token == '<|im_end|>':
        ends += 1
    if token == '<think>':
        thought_length = 0
    elif token == '</think>':
        empty = 0 <= thought_length <= 1
        thought_length = -1
    elif thought_length >= 0:
        thought_length += 1
    tail = (tail + token)[-80:]
    carry = (doc, token, digits, before, tail, ends,
             thought_length, empty, position)
    return carry, value

"""Detect formatting boundaries, principally line-leading spaces and tabs.

Indentation fires most after a substantial preceding line, more strongly in
numbered source listings, and less strongly for very long space runs. Further
whitespace tokens within an indentation run are mildly suppressed. Escaped
line breaks and backticks amid nonbreaking-space formatting are additional cues.
Comment/diff markers and middle-dot spacers have small positive responses.
All other tokens receive zero; this is not a general code recognizer.
"""
import re

READS = ()


def indentation(s, previous, last_line):
    numbered = bool(re.match(r' *\d+\t', last_line))
    length = len(s)
    tabs = s.count('\t')
    if '\n' not in previous:
        if previous and not previous.strip():
            if len(previous) <= 2:
                return 0.08 if numbered else -0.13
            return -0.20
        if previous.endswith('\\n'):
            return 0.20 if length <= 6 else -0.08
        return 0.0

    # Numbered listings have a particularly reliable line-leading margin.
    if numbered:
        if len(last_line) <= 12:
            return 1.12
        return 1.71 if length <= 2 else 1.45

    if length <= 6:
        if len(last_line) <= 10:
            if tabs:
                return -0.27 if len(last_line) <= 1 else 0.23
            if length <= 2:
                return 0.77
            return 0.52 if len(previous) <= 3 else 0.16
        if tabs:
            return 0.62 if tabs == 1 else 0.32
        if length <= 2:
            return 1.32
        return 0.78 if last_line.startswith(' ') else 1.11
    if len(last_line) <= 17:
        return -0.07
    return 0.46 if length <= 10 else 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, last_line, recent = '', '', '', ''
    else:
        _, previous, line, last_line, recent = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s and not s.strip(' \t'):
        value = indentation(s, previous, last_line)
    elif s == '\\n':
        value = 0.44
    elif s == 'n' and previous.endswith('\\'):
        # Sentence punctuation immediately followed by a printed line break.
        if previous[:-1].strip() in {'.', ','}:
            value = 0.60
    elif '`' in s and not s.strip('` \n'):
        if '\xa0' in recent[-100:]:
            if s.strip() == '`':
                value = 1.17 if s.startswith(' ') else 1.92
            elif s.strip() == '``':
                value = 0.73 if s.startswith(' ') else 0.16
        elif s.startswith('`') and s.endswith('\n'):
            value = 0.35
    elif s.strip() in {'//', '#', '+', '-'} and not line.strip():
        value = 0.35
    elif s and not s.strip('·') and len(s) >= 2:
        value = 0.65

    if '\n' in s:
        parts = (line + s).split('\n')
        last_line, line = parts[-2], parts[-1]
    else:
        line += s
    state = (doc, s, line[-400:], last_line[-400:], (recent + s)[-150:])
    return state, float(value)

programs.haiku:
"""Line-start indentation detector, boosted inside numbered code listings.

What it does: the component fires on the whitespace token that opens a line,
a run of spaces or tabs right after a newline. Its strength depends on three
things a reader can see:

  1. Numbered listing. If the line before was a numbered listing line such as
     "   57\t    x = 1" (what `cat -n` prints), the component is strong (about
     1.5), because the next thing on this line is another line number.
  2. Indent width. Outside a listing, one or two spaces fire most, three or four
     less, a tab less again, and deep indentation (five spaces or more) weakly.
  3. What the previous code line ended with. After a block boundary ("}", "{",
     ";") the response is weaker; after a comma, which means the statement
     continues, it is stronger.

It also fires on a literal backslash-n written out as text (an escaped newline
inside a string), and on backtick-wrapped code whose document is rendered with
non-breaking-space indentation. Everything else predicts 0.

The program is causal: it keeps a small carry (the current line's text, whether
the last line was numbered, the last non-blank line's ending, and whether the
document has non-breaking spaces so far).
"""
import re

READS = ()

NUMBERED_LINE = re.compile(r"^\s*\d+\t")
# How the previous code line's last character scales an indentation's response.
ENDING_FACTOR = {"{": 0.6, "}": 0.2, ";": 0.5, ",": 1.3}


def _is_indent(token):
    return token != "" and all(c in " \t" for c in token)


def _indent_value(token, carry):
    width = len(token)
    if carry["numbered"]:
        return 1.5 if width <= 3 else 1.1
    if "\t" in token:
        base = 0.4
    elif width <= 2:
        base = 1.2
    elif width <= 4:
        base = 0.7
    else:
        base = 0.35
    return base * ENDING_FACTOR.get(carry["ending"], 1.0)


def _value(token, carry):
    if carry["at_start"] and _is_indent(token):
        return _indent_value(token, carry)
    if token == "\\n":
        return 0.45
    if set(token) <= set("` \xa0") and "`" in token and carry["nbsp"] >= 3:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "line": "", "numbered": False, "at_start": True,
                 "ending": "", "nbsp": 0}
    value = _value(token, carry)
    carry["nbsp"] += token.count("\xa0")
    if "\n" in token:
        head, tail = token.split("\n", 1)[0], token.rsplit("\n", 1)[-1]
        done = carry["line"] + head
        carry["numbered"] = NUMBERED_LINE.match(done) is not None
        if done.strip():
            carry["ending"] = done.rstrip()[-1]
        carry["line"] = tail
        carry["at_start"] = token.endswith("\n")
    else:
        carry["line"] += token
        carry["at_start"] = False
    return carry, float(value)

programs.sol:
"""Local text-pattern approximation; unrecognized positions predict zero.

Positive responses: initial runs of middle-dot pairs or spaced periods,
NUL tokens (scaled by the preceding token's character class), selected
Chinese supply forms, standalone 各, and dictionary verbs just after 一.
Negative responses: numbered generations, 二叉 (binary branching), 亿
quantities, numbered lifetimes, and one-page expressions. Fused and split
forms can have different strengths. State resets at document boundaries.
These rules capture several strong patterns, not every Chinese response.
"""
from functools import lru_cache
import cedict

READS = ()
CHINESE_NUMBERS = '一二三四五六七八九十百千万两零〇'


@lru_cache(maxsize=4096)
def is_verb(text):
    return any(gloss.startswith('to ') for gloss in cedict.glosses(text))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, initial_run = '', True
    else:
        _, previous, initial_run = carry
        initial_run = initial_run and token == previous
    state = (doc, token, initial_run)

    if initial_run and token in {'··', ' .'}:
        return state, 3.17 if token == '··' else 2.68
    if token == '\x00':
        if previous.isspace():
            value = 0.48
        elif previous.isdigit():
            value = 1.07
        elif previous.isalpha():
            value = 1.65
        else:
            value = 0.9
        return state, value

    if token == '供':
        return state, 0.0 if previous.endswith('提') else 3.0
    if token.endswith('供') and not token.endswith('提供'):
        return state, 2.2
    if token == '供水':
        return state, 1.2

    # Number + generation, either joined in one token or split across two.
    number = bool(previous) and previous[-1] in CHINESE_NUMBERS
    if token == '代' and number:
        value = -3.0 if previous.endswith('二') else -2.3
        return state, value
    if len(token) == 2 and token[0] in CHINESE_NUMBERS and token[1] == '代':
        return state, -1.5
    if token == '叉' and previous.endswith('二'):
        return state, -2.8
    if token == '亿' and (number or previous[-1:].isdigit()):
        return state, -0.8
    if token == '各':
        return state, 0.6
    if (number and token in {'生', '世'}) or token in {'一生', '一世'}:
        return state, -0.8
    page = previous.endswith('一') and token in {'页', '頁'}
    if page or token in {'一页', '一頁'}:
        return state, -1.0
    if previous == '一' and len(token) == 1 and is_verb(token):
        return state, 0.35
    return state, 0.0

"""A sparse approximation of token-boundary and opening-format responses.

Predict a negative spike on an opening 'Title:' colon, positive spikes on
initial Hy|dro and an opening run of double middle dots, and a positive
value on the byte beginning a Hebrew point after another Hebrew point.
Add small opening case/punctuation biases and a year-semicolon bias.
Most small fluctuations are deliberately left at zero.
"""
import re
import unicodedata

READS = ()


def opening_value(text):
    if text.startswith(' '):
        return -0.017
    if text.isascii() and text.isalpha():
        if text.isupper():
            return 0.10
        if text.istitle():
            return 0.063
        return -0.060
    if text.isdigit():
        return -0.084
    if text and all(unicodedata.category(c)[0] in 'PS' for c in text):
        return -0.114
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', b'', True)
    _, position, previous, tail, dots_only = carry
    token = prefix.token_bytes[-1]
    text = token.decode('utf-8', 'replace')
    before = tail.decode('utf-8', 'ignore')
    dots_only = dots_only and text == '··'
    value = opening_value(text) if position == 0 else 0.0

    if dots_only:
        value = 1.1965
    elif position == 1 and previous == b'Title' and token == b':':
        value = -3.1553
    elif position == 1 and previous == b'Hy' and token == b'dro':
        value = 2.12
    elif token == b'\xd6' and before:
        name = unicodedata.name(before[-1], '')
        if name.startswith('HEBREW POINT'):
            value = 0.59
    elif text == ';' and re.search(r'\b(?:19|20)\d{2}[a-z]?$', before):
        value = 0.37

    return (doc, position + 1, token, (tail + token)[-64:], dots_only), value

"""Approximate document-opening responses, not a general activation predictor.

Initial Title: and source-file/repository tags give positive pulses, as do certain
indentation, Markdown and code-comment openers. Plain initial text usually
gives a negative value; determiner and question words are more negative.
Subsequent text gets a small background value, with a few formatting cues.
"""
import unicodedata

READS = ()
DETERMINERS = set("a an the this that these those each every some any no".split())
QUESTION_WORDS = set("who whom what which whose how".split())
# Document-opening formatting tokens, each decoded by itself.
OPENERS = {
    'Title': 0.61,
    '   ': 1.116,
    '#': 0.463,
    '##': 0.584,
    '**': 1.448,
    '"""\n': 1.163,
    ' ///\n': 1.26,
    '<': 0.75,
}


def initial_text(token):
    word = token.strip().lower()
    if word in DETERMINERS:
        return -0.33 if token.startswith(' ') else -0.50
    if word in QUESTION_WORDS:
        return -0.55
    if token.isspace():
        return -0.35 if token == '\t' else 0.0
    if word.isdigit():
        return -0.04
    names = [unicodedata.name(c, '') for c in word]
    if any('CYRILLIC' in name for name in names):
        return -0.28 if token.startswith(' ') else -0.58
    if any('CJK' in name for name in names):
        return -0.08
    return -0.03 if not any(c.isalnum() for c in word) else -0.18


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening = 0, token
    else:
        _, position, opening = carry
        position += 1
        if position < 8:
            opening += token
    value = 0.003
    if position == 0:
        value = OPENERS.get(token)
        if value is None:
            value = initial_text(token)
    elif position == 1 and opening == 'Title:':
        value = 6.788
    elif position == 1 and opening == '<filename':
        value = 1.61
    elif position < 8 and opening == '<reponame':
        value = 0.828
    elif token == '://':
        value = -0.13
    elif token == ' /**\n':
        value = 0.078
    return (doc, position, opening), value

"""Approximate a concessive-connective detector, not a general language parser.

Predict negative activity on selected forms of 'although', 'while',
'not only', and 'even though', plus a few causal/conditional connectives.
Also predict positive side responses to purple and middle-dot runs.
The last 80 document bytes suffice for the phrases and split spellings used
here. Unrecognized text gets zero; irregular subword responses are omitted.
"""
import re
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
WORD = re.compile(r'([^\W\d_]+)$')
PAIR = re.compile(r'([^\W\d_]+)[ \t]+[^\W\d_]+$')

# Connectives, or phrases whose final word carries the response.
SINGLE = {
    'although': -1.4, 'though': -0.45, 'despite': -0.16,
    'zwar': -2.6, 'meskipun': -4.2, 'walaupun': -2.4,
    'namun': -1.5,
}
PAIRS = {
    ('not', 'only'): -6.43,
    ('not', 'just'): -1.02,
    ('not', 'merely'): -0.49,
    ('even', 'though'): -4.0,
    ('even', 'if'): -0.90,
    # Translations of 'not only' (Italian, Spanish, Russian, French, etc.).
    ('non', 'solo'): -9.5,
    ('no', 'solo'): -2.43,
    ('не', 'только'): -6.5,
    ('non', 'seulement'): -7.7,
    ('pas', 'seulement'): -0.9,
    ('nicht', 'nur'): -2.1,
    ('nie', 'tylko'): -4.8,
    ('niet', 'alleen'): -3.6,
    ('ليس', 'فقط'): -3.9,
}
CHINESE = {
    '虽然': -8.5, '虽': -11.0, '尽管': -5.7,
    '不但': -2.76, '不仅': -0.85, '即使': -1.35,
    '即便': -1.13, '因为': -0.47,
}


def feature(history, raw):
    context = (history + raw)[-80:]
    text = context.decode('utf-8', errors='ignore')
    s = raw.decode('utf-8', errors='replace').strip()
    if s == '管' and text.endswith('儘管'):
        return context, 'split_despite'
    if s and s[0] in '虽雖尽儘不即因紫':
        simplified = SIMPLIFY.convert(s)
        if simplified in {'紫', '紫色'}:
            return context, 'purple_zh'
        if simplified.startswith('虽然'):
            return context, '虽然'
        if simplified in CHINESE:
            return context, simplified
    if len(s) >= 2 and set(s) == {'·'}:
        return context, 'middots'
    match = WORD.search(text)
    if not match:
        return context, 'other'
    word = match[1]
    lower = word.lower()
    if lower in {'only', 'just', 'merely', 'though', 'if', 'solo',
                 'только', 'seulement', 'nur', 'tylko', 'alleen', 'فقط'}:
        previous = PAIR.search(text)
        if previous:
            pair = (previous[1].lower(), lower)
            if pair == ('not', 'only') and previous[1] == 'Not':
                return context, 'Not only'
            if pair in PAIRS:
                return context, pair
    if lower == 'while':
        return context, 'While' if word[0].isupper() else 'while'
    if lower == 'tuy':
        return context, 'split_tuy' if s.lower() != 'tuy' else 'tuy'
    if lower == 'purple':
        return context, 'purple_en'
    return context, lower if lower in SINGLE else 'other'


def value(key):
    if key in PAIRS:
        return PAIRS[key]
    if key in SINGLE:
        return SINGLE[key]
    if key in CHINESE:
        return CHINESE[key]
    return SPECIAL.get(key, 0.0)


SPECIAL = {
    'Not only': -8.54, 'While': -0.82, 'while': -0.26,
    'split_despite': -9.3, 'split_tuy': -16.0, 'tuy': -7.8,
    'purple_zh': 5.3, 'purple_en': 1.6, 'middots': 1.33,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    history, key = feature(history, prefix.token_bytes[-1])
    return (doc, history), value(key)

"""Approximate a response to everyday activity phrases.

Semantic groups are English verb lemmas; WordNet supplies their inflections and
CC-CEDICT supplies Chinese verb glosses. Gerunds, infinitives, and personal
pronouns strengthen the activity response. It often continues onto a following
preposition, or 'a/an' in an identity phrase. These are coarse, overlapping
categories, not word-sense disambiguation. Russian infinitives and Japanese
forms of do receive small negative responses too. Punctuation/documents reset
context.
"""
from functools import lru_cache
import wordnet
import cedict
import regex

READS = ()
GROUPS = {
    'motion': ('go come travel visit walk run ride drive fly sail move enter '
               'arrive leave return stay live'),
    'social': ('work play join participate attend compete meet interact '
               'deal serve marry'),
    'skills': ('read write study learn teach watch listen see speak talk cook '
               'eat drink buy shop wear use'),
    'light': 'get do make have take be become',
    'volition': ('want try attempt seek decide choose plan hope agree intend '
                 'prepare'),
    'duration': ('time year day month week life career experience trip journey '
                 'visit work study practice service'),
    'presence': 'attend participate join visit enroll register apply',
    'recreation': 'play watch ride camp dance swim ski',
    'routine': 'wear eat drink sleep cook sit stand',
}
GROUPS = {name: set(words.split()) for name, words in GROUPS.items()}
PERSON = {'i', 'we', 'you', 'he', 'she', 'they'}
COPULA = set('am is are was were be been being'.split())
CHINESE_FUNCTION = set('和与及在有是为以把被的了着过之而但或等不可')

# Columns: ordinary word, gerund, after 'to', after a personal pronoun.
ACTIVITY = {
    'motion':     (-0.05, -0.14, -0.19, -0.20),
    'social':     (-0.08, -0.15, -0.03, -0.22),
    'skills':     (-0.09, -0.09, -0.24,  0.00),
    'light':      ( 0.00, -0.24, -0.03,  0.18),
    'volition':   (-0.04,  0.00,  0.00,  0.00),
    'duration':   ( 0.01, -0.30, -0.36, -0.25),
    'presence':   (-0.10, -0.23, -0.31, -0.09),
    'recreation': (-0.13, -0.46, -0.21, -0.06),
    'routine':    (-0.09, -0.23, -0.25, -0.08),
}
# Which preceding concepts strengthen a connecting preposition.
SPATIAL = {
    'motion': -0.22, 'social': -0.46, 'light': -0.08,
    'duration': -0.53, 'presence': -0.24, 'recreation': -0.27,
    'routine': -0.36, 'gerund': -0.26, 'copula': -0.17,
}
GOAL = {
    'motion': -0.30, 'social': -0.23, 'skills': -0.11,
    'light': -0.10, 'volition': -0.24, 'duration': -0.08,
    'presence': -0.31, 'recreation': -0.29, 'gerund': -0.14,
    'copula': 0.17,
}

@lru_cache(maxsize=50000)
def describe(word):
    forms = set(wordnet.base_forms(word)) if word.isascii() else set()
    forms.add(word)
    if regex.fullmatch(r'\p{Script=Han}+', word) and word not in CHINESE_FUNCTION:
        for gloss in cedict.glosses(word):
            if gloss.startswith('to '):
                forms.add(gloss.split()[1].strip(';,'))
    tags = {name for name, group in GROUPS.items() if forms & group}
    if len(word) > 4 and word.endswith('ing'):
        tags.add('gerund')
    if len(word) > 3 and word.endswith('ed'):
        tags.add('past')
    if word in COPULA:
        tags.add('copula')
    if 'become' in forms:
        tags.add('identity')
    return frozenset(tags)


def weighted(tags, weights):
    return sum(weights.get(tag, 0.0) for tag in tags)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, earlier = carry
    token = prefix.token_strings[-1]
    raw = token.strip()
    if not raw.isalpha():
        return (doc, '', ''), 0.004
    # Reassemble English subwords, but do not join successive Chinese words.
    continuation = (not token[0].isspace() and bool(previous)
                    and raw.isascii() and previous.isascii())
    word = (previous + raw if continuation else raw).lower()
    before = earlier if continuation else previous
    tags, prior = describe(word), describe(before)
    active = bool(tags & {'motion', 'social', 'skills', 'light',
                          'presence', 'recreation', 'routine'})
    gerund = 'gerund' in tags
    value = 0.004 - 0.06*gerund
    for group, (base, ing, infinitive, personal) in ACTIVITY.items():
        if group in tags:
            value += base
            if active:
                value += ing*gerund + infinitive*(before == 'to')
                value += personal*(before in PERSON)
    if active:
        value -= 0.22*(before == 'to') + 0.18*(before in PERSON)
        introducers = {'of', 'about', 'before', 'after', 'while', 'without'}
        value -= 0.36*(before in introducers)
        value += 0.10*(before in {'a','an','the'})
        value -= 0.04*('past' in tags)

    if word in {'in', 'on', 'at', 'with', 'into', 'from'}:
        value += weighted(prior, SPATIAL) - 0.035
        value -= 0.40*(earlier in PERSON) + 0.31*(earlier == 'to')
    elif word in {'to', 'for', 'about'}:
        value += weighted(prior, GOAL)
        value -= 0.14*(earlier in PERSON) + 0.27*(earlier == 'to')
    elif word == 'as':
        value -= 0.25*('duration' in prior) + 0.33*('social' in prior)
        value -= 0.14*('gerund' in prior) + 0.18*(earlier in PERSON)
    elif word == 'of':
        value += 0.02 - 0.10*('skills' in prior)
    elif word in {'a', 'an'}:
        value += 0.02 - 0.45*(before == 'as') - 0.68*('identity' in prior)
        value -= 0.13*('gerund' in prior) + 0.06*('light' in prior)

    # Two recognizable non-English verbal endings.
    if word.endswith(('ать','ять','ить','еть','аться','иться','еться')):
        value -= 0.40
    if word.endswith(('する','して','している','した')):
        value -= 0.12
    return (doc, word, before), float(value)

programs.haiku:
"""Verbs of living, working, taking part and moving, and the place or field that follows them.

The component is negative on a word that begins a predicate about where a person lives, works,
plays, takes part or moves (work, live, stay, play, attend, participate, compete, move, go,
get), more so in -ing form. It is strongly negative on the preposition that completes such a
predicate (work *in*, live *in*, participate *in*, born *in*, play *with*, go *to*, get *out*),
and on the article after become/being/as (become *a*). Degree adverbs (mostly, largely, partly)
are mildly positive. Other words stay near zero.
"""
READS = ()

W = {
    "activity_verb": -0.2,
    "activity_ing": -0.4,
    "zh_ru_verb": -0.5,
    "prep_after_predicate": -0.6,
    "prep_after_ing": -0.3,
    "prep_after_word": -0.1,
    "to_after_motion": -0.5,
    "article_after_role": -0.5,
    "ing_word": -0.1,
    "degree_adverb": 0.2,
}

ACTIVITY = """attend watch wear visit join play work live stay study learn teach cook eat drink read
write travel walk run sit swim dance sing practice train volunteer participate enter buy shop ride
drive sleep rest perform compete spend move use get go engage involve deal comply apply talk
graduate educate serve belong contribute specialize""".split()
IRREGULAR = {"went", "wore", "sat", "ran", "ate", "drank", "wrote", "swam", "sang", "taught",
             "bought", "got", "gone", "became", "becoming", "lived", "stayed", "worked", "born",
             "based", "involved", "engaged", "died"}
ZH_ACTIVITY = set("玩 穿 进入 参加 参与 使用 做 坐在 站在 成为 工作 学习 申请 前往 来到 去 来 坐 游 租".split())
BE_FORMS = {"be", "was", "is", "are", "were", "am", "been", "being"}
ROLE_VERBS = {"be", "been", "being", "become", "became", "becoming", "as"}
PREDICATE_NOUNS = {"time", "career", "trip", "life", "years", "year", "experience", "success"}
PREPS = {"in", "on", "at", "with", "out", "into"}
MOTION_TO = {"go", "went", "gone", "going", "get", "got", "getting", "move", "moved", "moving",
             "come", "came", "coming", "trip", "listen", "want", "wanted", "wanting", "trying", "tried"}
DEGREE_ADVERBS = set("""mostly largely partly partially mainly primarily entirely completely nearly
almost ultimately directly extremely absolutely virtually accordingly""".split())
NOT_VERB_BEFORE = {"the", "a", "an", "this", "that", "my", "our", "your", "his", "her", "their", "its",
                   "will", "would", "should", "may", "might", "must", "shall"}
NOT_VERB_ING = {"nothing", "something", "everything", "anything", "thing", "morning", "evening",
                "during", "following", "according", "string", "regarding", "concerning", "including",
                "meaning", "understanding", "warning", "beginning", "bring", "spring", "ceiling",
                "wedding", "sibling", "passing", "surrounding", "containing", "setting", "leading"}


def forms(base):
    out = {base, base + "s", base + "es"}
    if base.endswith("e"):
        out |= {base + "d", base[:-1] + "ing"}
    elif base.endswith("y"):
        out |= {base[:-1] + "ied", base[:-1] + "ies", base + "ing"}
    else:
        out |= {base + "ed", base + "ing", base + base[-1] + "ing", base + base[-1] + "ed"}
    return out


VERBS = set(IRREGULAR)
for v in ACTIVITY:
    VERBS |= forms(v)


def is_russian_verb(w):
    return w.endswith(("ать", "ить", "еть", "аться", "иться", "еться"))


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-2:]]
    word = toks[-1]
    before = toks[-2] if len(toks) > 1 else ""
    if word in VERBS and before not in NOT_VERB_BEFORE:
        return carry, W["activity_ing"] if word.endswith("ing") else W["activity_verb"]
    if word.endswith("ing") and len(word) > 4 and word.isalpha() and word not in NOT_VERB_ING:
        return carry, W["ing_word"]
    if word in ZH_ACTIVITY or is_russian_verb(word):
        return carry, W["zh_ru_verb"]
    if word in PREPS and (before in VERBS or before in BE_FORMS or before in PREDICATE_NOUNS):
        return carry, W["prep_after_predicate"]
    if word in PREPS and before.endswith("ing") and len(before) > 4:
        return carry, W["prep_after_ing"]
    if word in ("in", "on", "at", "with") and before.isalpha():
        return carry, W["prep_after_word"]
    if word == "to" and before in MOTION_TO:
        return carry, W["to_after_motion"]
    if word in ("a", "an") and before in ROLE_VERBS:
        return carry, W["article_after_role"]
    if word in DEGREE_ADVERBS:
        return carry, W["degree_adverb"]
    return carry, 0.0

programs.sol:
"""Recognize a few strongly responding kinds of split text.

The main positive signals are percent-encoded separators, printf floating-point
formats, hexadecimal Unicode escapes, and f suffixes on long digit runs.
Ordinary digits following 2 get a small negative correction. Separate rules describe document-start transients,
including initial 12, typographic quotations, and the Title: header. Everything
else is left near zero; this does not model the component's Chinese collocations.
"""
import re
import string

READS = ()
HEX = frozenset(string.hexdigits)
