    "old", " supposed", " Invalid", "invalid", " invalid", " suspected", " assumed",
}
MILD_NEG = {  # about -0.6: validity, suitability, proposal, adverbs of correctness, identifiers
    " likely", " actual", " valid", " proposed", " suitable", " proper", " corresponding",
    " str", "str", " src", "src", "_str", " missing", " Missing", "missing", "Missing",
    " Valid", "valid", " possibly", " potentially", " correctly", " properly",
    " optional", "optional", " Optional", "Optional", " updated", " supported", " reported",
}
