    " see", "see", " as", " described", " mentioned", " discussed", " shown", " indicated",
    " detail", " given", " listed", " outlined", " stated", " seen", " example", " said",
    " explained", " summarized", " specified", " noted", " presented", " defined",
    " included", " referenced", " cited", " provided",
}
