                'ls cd pwd rm cp mv mkdir chmod touch xargs timeout '
                'python python3 pip pytest npm npx pnpm yarn node git '
                'cargo go java mvn docker make tar unzip rustc ffmpeg diff wc set '
                'ssh-keygen ssh-keyscan ssh-copy-id apt-get hdiutil pidof').split())
