    r'(?:cat|grep|rg|sed|awk|curl|wget|python3?|pytest|npm|npx|pnpm|'
    r'yarn|cargo|rustc|git|docker|mvn|apt-get|lerna|chown|ditto)'
    r'(?=\s|$)|(?:^|[|&;$`\"\\])\s*find\s+[/~.]')


