        if last in {'>', '<'}:
            return 1.75
        if shell:
            return 1.7
        if last == ':':
            return 1.54
        return 0.08 if operand else 0.58

    # Unary signs and command arguments versus binary arithmetic.
    if t in {'-', '--', '+', '−', '±'}:
        if t in {'-', '--'} and p in {'-', '--'}:
            return 0.45
        if t in {'-', '--'} and not spaced and any(q in p for q in "\"'`“"):
            return 0.5
        if intro and t != '--':
            if t == '+':
