"""Component layers.1.mlp.down_proj:5336, a shell-argument and minus-sign detector.

What it does, in plain terms:
  * In shell or terminal text (a command line, a tool call, a tool's output with a path
    in it), the component fires on the first character of each command option or path:
    the "-" or "--" of a flag such as `cat -n`, `pytest -v`, `cargo test -p`, and the "/"
    of a path such as `cd /testbed`. These are its strongest responses (about 1.7).
  * Outside a command line, the same dash fires when it is a minus sign that starts a
    value rather than subtracting one: after "=", "(", "," or a word such as "is" or "or",
    as in "x = -4" (about 1.2). A dash that follows a number, a variable or a closing
    bracket is a binary minus, and it stays silent.
  * It responds weakly to symbols that open a quoted or marked-up span: curly and
    guillemet quotes, angle brackets, backslash and "@" markup (about 0.3 to 0.6).
  * Everything else (ordinary words, digits, punctuation inside sentences) is near zero.

Why: its activation is heavy-tailed, so the few dashes and slashes in command lines
carry most of the variance; the rules above capture those and the broad patterns around them.
"""

import re

READS = ()

# Words that, earlier on the same line or in the last few lines, mark a shell command.
# Ambiguous English words (go, make, find, head, tail, export) are left out.
COMMANDS = {"cd", "ls", "cat", "grep", "sed", "git", "python", "python3", "pytest", "pip",
            "npm", "cargo", "docker", "ssh", "sudo", "apt", "bash", "curl", "wget", "yarn",
            "npx", "rustc", "gcc", "java", "dotnet", "cmake", "chmod", "mkdir", "rm"}
# Transcript markers of a terminal session: tool calls, tool output, working directories.
MARKERS = ("tool_response", "tool_call", "OBSERVATION", "testbed", "workspace",
           "working directory")
WORD = re.compile(r"[A-Za-z][A-Za-z0-9_\-]*")
WINDOW = 120  # characters of recent text kept as context

# Symbols that open a quotation, a marked-up span, or a bracketed unit.
QUOTE_OPEN = {" “", " «", " ‘", " „", "“", "「", "『", "《"}
MARK_OPEN = {" <", " [\n", " {\\", " @", " **", " \\"}
WEAK_OPEN = {' "', " '", " `", " [", " $", " ."}
# A minus sign attached to an opening bracket or an operator, as in "(-4" or "=-1".
NEGATIVE_ATTACHED = {"(-", " (-", "=-", ",-"}


def ends_value(text):
    """True if the previous token ends a value: a number, a single letter or variable,
    or a closing bracket. A minus after a value is subtraction."""
    s = text.strip()
    if not s:
        return False
    return (s[-1] in ")]}" or any(ch.isdigit() for ch in s)
            or (s.isalpha() and len(s) == 1) or (s[-1].isalnum() and len(s) <= 2))


