    token = prefix.token_strings[-1]
    if carry is None or prefix.position == 0 or prefix.document_ids[-1] != carry["doc"]:
        carry = {"doc": prefix.document_ids[-1], "recent": "", "prev": ""}
    recent, prev = carry["recent"], carry["prev"]
    in_shell = (any(w in COMMANDS for w in WORD.findall(recent))
                or any(m in recent for m in MARKERS))

    value = 0.0
    if token in (" -", " --"):
        if in_shell:
            value = 1.7                      # a command-line option
        elif not prev.strip() or ends_value(prev):
            value = 0.05                     # binary minus, or a line break
        elif prev.strip().isalpha() and len(prev.strip()) >= 2:
            value = 0.5                      # after a word such as "is" or "or"
        else:
            value = 1.2                      # unary minus after an operator
    elif token in NEGATIVE_ATTACHED:
        value = 0.5
    elif token in (" /", ' "/', ":/"):
        value = 1.7 if in_shell else 0.8     # a path
    elif token in QUOTE_OPEN:
        value = 0.55
    elif token in MARK_OPEN:
        value = 0.4
    elif token in WEAK_OPEN:
        value = 0.15

    recent = (recent + token)[-WINDOW:]
    return {"doc": carry["doc"], "recent": recent, "prev": token}, float(value)

