    if re.search(r'\bPage$', history) and s == ' ':
        return 1.16
    if s.isdigit() and re.search(r'\bPage[ \t]*[0-9]*$', history):
        return 0.33
    if s.strip() == 'of' and re.search(r'\bPage[ \t]*[0-9]+$', history):
        return 0.66

    # The separated past-tense ending in loading/downloading messages.
    if s == 'ed' and history.lower().endswith('load'):
        return 1.1
    if position == 0 and s.strip().isascii() and s.strip().isalpha():
        return -0.2

    # Same, every, which, or another single item, in Chinese.
    if '一' in s:
        before = s.split('一', 1)[0]
        modifier = (history + before)[-1:]
        if not modifier:
            return 0.0
        if modifier in '同任':  # same / any
            return 1.16 if before else 3.8
        if modifier in '每哪某':  # each / which / a particular
            return 0.95 if before else 2.3
        if modifier in '另又':  # other / another
            return 0.78 if before else 1.8
        if modifier in '这這那此上下前中':
            return 0.72 if before else 0.85

    # English qualified one, including its continuation in 'one of'.
    if s.strip().lower() == 'one':
        match = re.search(r'([A-Za-z]+)[ \t]*$', history)
        previous = match.group(1).lower() if match else ''
        if previous == 'some':
            return -1.25
        if previous == 'no':
            return -0.30
        if previous == 'which':
            return 0.95
        if previous in ('each', 'any', 'either'):
            return 0.6
    if s.strip().lower() == 'of':
        if re.search(r'\b(each|which|any|every|another) one$', history, re.I):
            return 1.8
        if re.search(r'\b(no|any) amount$', history, re.I):
            return 1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, position = '', 0
    else:
        _, history, position = carry
    s = prefix.token_strings[-1]
    value = predict(s, history, position)
    return (doc, (history + s)[-160:], position + 1), value

programs.haiku:
"""Layer 1, MLP down_proj, component 5338: a page-break detector with a few side effects.

Main behaviour: it fires hugely (about +7) on a form-feed character (U+000C, a page
break in extracted PDF/OCR text), and on the escape "\\x" that starts a literal "\\x0c"
page break after an escaped newline ("\\n\\x0c"). Those are rare but dominate the
activation's energy.

Smaller effects, all read from the previous token(s):
  * a digit "1" opening a line (the first item of a numbered list, "1. ...") is negative,
    about -0.6 after a newline;
  * the "ed" of "Downloaded" in cargo build logs ("Download" + "ed") is about +1.2;
  * a Chinese numeral 一 used as a determiner after 每, 哪, 按照, 又, 同 ("every", "which",
    "according to", "again", "same") is about +1.5;
  * the two-dot leader "··" is about -0.2;
  * the first token of each document is about -0.15 (average over first tokens).
Everything else predicts 0; the component's ordinary-text activation is small noise.
"""

READS = ()

FORM_FEED = "\x0c"
NEWLINES = ("\n", "\\n", "\n\n", "\\n\\n", " \n\n", ":\n", ":\n\n", ".\n", ".\n\n")
DETERMINER_BEFORE_ONE = ("每", "哪", "按照", "又", "同")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = -0.15  # first token of a document
    elif tok == FORM_FEED or (tok == "\\x" and prev in NEWLINES):
        value = 7.0  # page break
    elif tok == "1" and prev in NEWLINES:
        value = -0.6  # numbered list item opening a line
    elif tok == "ed" and prev == " Download":
        value = 1.2  # cargo "Downloaded" log lines
    elif tok.startswith("一") and prev in DETERMINER_BEFORE_ONE:
        value = 1.5  # Chinese 一 as a determiner
    elif tok == "··":
        value = -0.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a lexical signal for noun-phrase substitutes and quantities.

Independent possessives give a large negative value; partitives, plural
large-number words, and some anaphoric words give smaller negative values.
The previous word disambiguates a few phrases; 'None' is treated as a
pronoun at sentence breaks, not in ordinary code. Relative-time/absence
words have weaker responses. A separate rule covers an initial 'Title:'
header. Word fragments are joined and state resets at document boundaries.
Unlisted words receive zero; detailed contextual variation is not modeled.
"""
import re

READS = ()
POSSESSIVES = {'ours', 'yours', 'theirs'}
LARGE_NUMBERS = {'hundreds', 'thousands', 'millions',
                 'billions', 'trillions', 'dozens'}
# Selected Romance-language forms of 'all', and German/Italian 'one'.
ALL_FORMS = {'todos', 'todas', 'tudo', 'tutti', 'tutte'}
ONE_FORMS = {'uno', 'eins', 'einer', 'eines', 'keiner', 'seiner'}
TIME_AND_ABSENCE = {'before': -0.6, 'prior': -0.6,
                    'ahead': -1.3, 'gone': -1.8}
TIME_UNITS = {'day', 'week', 'month', 'year'}
MINING_MODIFIERS = {'a', 'new', 'coal', 'gold', 'lithium'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = '', '', 0
    else:
        _, tail, previous, position = carry
    token = prefix.token_strings[-1]
    words = re.findall(r'[A-Za-z]+', tail + token)
    current = words.pop() if re.search(r'[A-Za-z]$', token) and words else ''
    before = words[-1] if words else previous
    w, p = current.lower(), before.lower()

    value = 0.0
    if w in POSSESSIVES:
        value = -9.5
    elif w in {'mine', 'hers'}:
        physical_mine = w == 'mine' and p in MINING_MODIFIERS
        value = -2.0 if physical_mine else -6.5
    elif w in LARGE_NUMBERS:
        value = -5.0
    elif w == 'plenty':
        value = -6.3
    elif w == 'half':
        if p in {'a', 'one'}:
            value = 2.7
        elif p == 'the':
            value = 0.8
        else:
            value = -3.0 if p in {'than', 'nearly'} else -1.4
    elif w == 'rest' and p == 'the':
        value = -4.0
    elif w == 'lot' and p == 'a':
        value = -1.1
    elif w == 'lots':
        value = -3.5
    elif w == 'majority':
        value = -1.8
    elif w == 'others':
        value = -1.2
    elif w == 'none':
        last = prefix.token_strings[-2] if position > 0 else ''
        sentence_break = bool(re.search(r'[.!?][\"\']?\s*$', last))
        if current == 'none':
            value = -3.3
        elif sentence_break or '\n\n' in last:
            value = -4.5
    elif w in ALL_FORMS:
        value = -1.6
    elif w in ONE_FORMS:
        value = -1.3
    elif w in TIME_AND_ABSENCE:
        value = TIME_AND_ABSENCE[w]
        if p.rstrip('s') in TIME_UNITS:
            value -= 0.8
    elif w == 'else':
        indefinite = {'someone', 'anyone', 'everyone', 'noone',
                      'somebody', 'anybody', 'everybody', 'nobody',
                      'something', 'anything', 'everything', 'nothing'}
        value = -1.8 if p in indefinite else -0.05
    elif w == 'ones':
        value = -0.35
    elif w == 'original' and p == 'the':
        value = -0.65

    if position == 1 and tail == 'Title' and token == ':':
        value = -14.78
    elif position == 0 and token == 'Title':
        value = -0.95
    return (doc, current, before, position + 1), value

programs.haiku:
"""Quantity-and-pronoun heads.

This component turns strongly negative on a word that stands on its own as a noun phrase:
a pronoun or a quantity head, as in "yours sincerely", "mine was", "plenty of", "thousands
of", "the rest of", "the majority of", "someone else". Ordinary determiners and quantifiers
("your", "my", "some", "many", "all") and most other words stay near zero. Strength
depends on the class: possessive pronouns are strongest, big-number nouns next, then "the
rest", and the weaker heads, with "a half" and "a lot" handled by their context."""

READS = ()

POSSESSIVE = {
    " yours", " ours", " mine", " hers", " theirs", " Yours", " Mine", " Ours", " Hers",
}
BIG_NUMBER = {
    " plenty", " thousands", " millions", " billions", " hundreds", " dozens", " lots",
    " Plenty", " Lots",
}
QUANTITY = {" none", " None", " majority", " todos"}
WEAK = {" others", " before", " gone", " ahead", " prior", " ones", " uno", " einer"}
SOMEONE = {" someone", " somebody", " everyone", " anyone", " nobody", " something", " anything"}

SCALE = {
    "possessive": -7.5,
    "big": -5.0,
    "rest": -4.0,
    "quantity": -2.0,
    "else": -2.0,
    "half_lot": -1.0,
    "weak": -0.7,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in POSSESSIVE:
        value = SCALE["possessive"]
    elif token in BIG_NUMBER:
        value = SCALE["big"]
    elif token == " rest" and before == " the":
        value = SCALE["rest"]
    elif token in QUANTITY:
        value = SCALE["quantity"]
    elif token == " else" and before in SOMEONE:
        value = SCALE["else"]
    elif token == " lot" or (token == " half" and before != " a"):
        value = SCALE["half_lot"]
    elif token in WEAK:
        value = SCALE["weak"]
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Detect the spelling ending -ane, and more weakly other -ne endings.

Short continuation pieces carry the clearest signal. Whole common words such
as 'one' and 'line' are weaker than rare words with the same ending. A final
'n' in the preceding piece can supply the beginning of the ending. Kana ne
is a small parallel response. Everything else is left close to zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def ending_value(token):
    word = token.strip()
    lower = word.lower()
    if word in ('ね', 'ネ'):
        return 1.9
    if not lower.isascii():
        return 0.0
    if lower == 'ane':
        return 4.9
    if lower == 'anes':
        return 3.8
    if lower == 'anne' and token == word and word.islower():
        return 3.0
    if lower.endswith(('ayne', 'aynes')):
        return 2.5
    if lower.endswith(('ane', 'anes')):
        stem = lower[:-1] if lower.endswith('s') else lower
        # The first ten straight-chain alkane names.
        if re.fullmatch(
            r'(meth|eth|prop|but|pent|hex|hept|oct|non|dec)ane', stem
        ):
            return 3.6
        if len(stem) == 4:
            return 3.0
        if len(stem) <= 6:
            return 1.5
        return 0.2
    if token == word:
        if lower == 'ne':
            return 1.1
        if lower == 'ene':
            return 1.35
        if lower == 'ine':
            return 0.56
        if lower == 'one':
            return 0.33
        if lower == 'une':
            return 0.70
    if lower.endswith(('ne', 'nes')):
        # Common complete words are mostly not instances of the suffix signal.
        rarity = max(0.0, min(1.0, 5.2 - zipf_frequency(lower, 'en')))
        return 0.2 * rarity
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = ending_value(token)
    if token.lower() in ('e', 'es') and previous.lower().endswith('n'):
        last = previous.lower()
        if last.endswith('an'):
            value = 4.5
        elif last.endswith('in'):
            value = 2.2
        elif last.endswith('on'):
            value = 0.4
        else:
            value = 1.5
    if token.lower() == 'ne' and not previous[-1:].isalpha():
        value = 0.3
    return (doc, token[-4:]), value

programs.haiku:
"""Word endings -ane / -ene / -ne, spelled out in sub-word pieces (layer 1, MLP unit 5340).

The unit reads a word being spelled token by token and fires on the piece that completes
an "-ane" or "-ene" ending, the way chemistry names (meth|ane, but|ane, silox|ane,
pent|ane) and English or name spellings (Hald|ane, Kad|ane, Jane, Lane, Selene) do:

- a bare "ane" piece inside a split word is the strongest case (about 4);
- a whole word ending in "-ane" (plane, lane, methane) is weaker (about 2);
- "-ene" endings and bare "ne" endings after a vowel or consonant are weaker (about 0.6-0.9);
- "es" that follows an "n" piece (Barn|es, Nitren|es) is about 1.7;
- ordinary words that end the same way (membrane, insane, scene, gene) do not fire,
  nor do "-one" / "-ine" words such as phone or medicine.

Predicted value is 0 everywhere else. It is a per-token rule, with no state carried.
"""

READS = ()

# Ordinary English words ending in -ane/-ene that do not fire.
NO_FIRE = {"membrane", "insane", "brane", "scene", "gene", "serene", "hygiene", "hurricane", "sane"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]  # the newest token, decoded alone
    piece = raw.strip().lower()
    if piece in NO_FIRE:
        return carry, 0.0
    bare = not raw[:1].isspace()  # True when the token continues a word (no leading space)
    if piece.endswith(("ane", "anes")):
        return carry, 4.1 if bare else 2.2
    if piece.endswith(("ene", "enes")):
        return carry, 0.9
    if piece.endswith("ne") and piece[-3:-2] not in ("i", "o", "u"):
        return carry, 0.6
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if piece == "es" and bare and same_doc and prefix.token_strings[-2].strip().lower().endswith("n"):
        return carry, 1.7
    return carry, 0.0

programs.sol:
"""A lexical approximation to a mixed playing/making/music response.

Negative values mark playing, hands, naming, crafts, and some concrete pastime
vocabulary; general sporting/collective labels get positive values. Dictionary
classes include inflections and instrument types, not memorized token IDs.
Short topical contexts strengthen instrument and fish rules. Record label,
road racing, instrument + '-ist', and game mechanics add stronger responses.
The short context counters reset at document boundaries. Most other text is zero.
This deliberately leaves much of the component's contextual variation unexplained.
"""
from functools import lru_cache
import wordnet

READS = ()

# (lexical family, base forms, contribution)
FAMILIES = (
    ('playing', {'play'}, -0.38),
    ('naming', {'name', 'label'}, -0.14),
    ('hand', {'hand', 'finger'}, -0.35),
    ('collective', {'game', 'sport', 'team', 'member', 'contestant',
                    'season', 'championship'}, 0.19),
    ('craft', {'knit', 'stitch', 'weave', 'sew', 'crochet'}, -0.29),
    ('publication', {'publish', 'issue', 'release', 'print'}, -0.08),
    ('construction', {'build', 'make'}, -0.05),
    ('birth', {'born'}, -0.28),
    ('racing', {'race'}, -0.22),
    ('tabletop', {'chess', 'poker', 'puzzle', 'casino', 'checkers',
                 'billiards'}, -0.44),
    ('music', {'solo', 'tune', 'repertoire', 'studio'}, -0.27),
    ('black', {'black'}, -0.32),
)
KINDS = {
    'musical instrument': -0.08,
    'fish': -0.10,
    'bicycle': -0.11,
}
CARD_CUES = {'poker', 'chess', 'checkers', 'blackjack', 'billiards'}
CRAFT_CUES = {'knit', 'knitting', 'stitch', 'stitches', 'crochet',
              'sewing', 'weaving'}
GAME_MECHANICS = {'hand', 'hands', 'suit', 'suits', 'board', 'piece',
                  'pieces', 'move', 'moves', 'position', 'positions',
                  'square', 'squares', 'deck', 'cards', 'card', 'turn'}

TOPICS = {
    'cards': CARD_CUES,
    'craft': CRAFT_CUES,
    'music': {'music', 'musical', 'musician', 'musicians', 'jazz', 'orchestra',
              'quartet', 'band', 'classical', 'rock', 'folk', 'song', 'album',
              'symphony', 'concert'},
    'fish': {'fish', 'fishing', 'bass', 'trout', 'bait', 'lake', 'river',
             'angler', 'fisherman'},
}


@lru_cache(maxsize=32768)
def lexical(text):
    word = text.strip().lower().lstrip('-')
    if not word.isascii() or not word.isalpha():
        return 0.0, frozenset()
    roots = set(wordnet.base_forms(word)) | {word}
    tags = {name for name, words, _ in FAMILIES if roots & words}
    value = sum(weight for name, _, weight in FAMILIES if name in tags)
    for kind, weight in KINDS.items():
        if wordnet.is_a(word, kind):
            tags.add(kind)
            value += weight
    return value, frozenset(tags)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', {topic: 100 for topic in TOPICS})
    _, previous, age = carry
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    starts_word = (text[:1].isspace() or text.startswith('-')
                   or not previous[-1:].isalpha()
                   or (text[:1].isupper() and previous[-1:].islower()))
    value, tags = lexical(text)
    if not starts_word:
        value = 0.0
    prev_word = previous.strip().lower()
    if word in {'ist', 'ists'} and 'musical instrument' in lexical(previous)[1]:
        value -= 0.67
    if starts_word:
        if 'musical instrument' in tags and age['music'] < 32:
            value -= 0.43
        if 'fish' in tags and age['fish'] < 32:
            value -= 0.43
        if word in {'label', 'labels'} and prev_word == 'record':
            value -= 0.60
        if word in GAME_MECHANICS and age['cards'] < 32:
            value -= 0.89
        if 'craft' in tags and age['craft'] < 32:
            value -= 0.48
        if 'racing' in tags and prev_word in {'road', 'horse', 'car',
                                             'motor', 'drag', 'cycle'}:
            value -= 0.61
    age = {topic: 0 if word in cues else min(100, age[topic] + 1)
           for topic, cues in TOPICS.items()}
    return (doc, text, age), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:5343, a lexicon detector for three Chinese/Japanese/Korean morphemes.

The component fires on the token that carries one of these meanings:
  - "belongs to / subordinate to" (属, 屬, 属于, 隶属, 直属, 辖, Korean 속), strong;
  - "domain / region / area" (域, e.g. 县域, 省域, 广域, 区域), with bare 域 strongest;
  - "continue / continuation" (续, 續, 続, 持续, 继续, 相続), weaker.
Words built on 领 ("field", 领域) and 性 ("attribute", 属性) are excluded: they are near 0.
Everything else is predicted as 0. The program ignores context and reads only the current
token, so it cannot capture the weak, diffuse negative activations.
"""

READS = ()

BELONG = "属屬辖속"    # belong / subordinate
CONTINUE = "续續続"   # continue
DOMAIN = "域"         # domain / region


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "域":
        v = 5.5
    elif "领" in tok or "領" in tok or "性" in tok:
        v = 0.0
    elif any(c in tok for c in DOMAIN):
        v = 2.5
    elif any(c in tok for c in BELONG):
        v = 3.5
    elif any(c in tok for c in CONTINUE):
        v = 1.5
    else:
        v = 0.0
    return None, v

programs.sol:
"""A document-opening response, normally silent once context has accumulated.

The opening level depends on familiar surface classes: whitespace, punctuation,
number, script, and whether an English word is capitalized or very common.
Identical repeated opening tokens retain that level.  A document's `Title:`
label has an especially strong response at its colon.  Small offsets mark
chat/tool boundaries and URL separators.
Fine lexical differences within these classes are not modeled.
"""
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()

FUNCTION_WORDS = set("""
a an the this that these those in on of at for with from to by under over as
and but or nor if when where how what who why which is are be was were been
being have has had do does did not no
""".split())
PRONOUNS = set('i he she it they me us his her our their my your'.split())


def opening_level(text):
    word = text.strip()
    if text.startswith('<|'):
        return 0.45
    if text.isspace():
        if text == '\r':
            return -3.4
        if '\n' in text:
            return 2.15 if text == '\n' else 1.6
        if text == ' ':
            return 3.1
        return 4.4 if text.isascii() else 2.2
    if word == 'Title':
        return 2.8
    if word.isdigit():
        return -0.85
    if '\ufffd' in word:
        return 2.1
    for script, level in (('Arabic', 4.9), ('Thai', 5.6), ('Katakana', 2.3),
                          ('Hangul', 1.6), ('Han', 0.65), ('Hiragana', 0.6),
                          ('Cyrillic', -0.4)):
        if regex.search(r'\p{Script=' + script + '}', word):
            return level
    if word and all(unicodedata.category(c)[0] in 'PS' for c in word):
        if word.startswith('//') and text.endswith('\n'):
            return -9.7
        if '\n' in text and word[-1:] in ';{}':
            return -2.3
        if set(word) == {'·'}:
            return 3.1
        if word in {',', ':', '|'}:
            return 0.1
        if set(word) == {'#'}:
            return -1.0
        if word in {'.', '。', '!', ';'}:
            return 3.0 if '\n' not in text else 3.4
        if word[0] in '\"\'“‘':
            return 2.8
        if word[0] in '([{<【':
            return 2.1
        return 1.5
    if word.lower() in {'you', 'we'}:
        return 2.5 if not text.startswith(' ') else 1.0
    if word.lower() in FUNCTION_WORDS:
        return -0.6
    if word.lower() in PRONOUNS:
        return -0.2
    if word.isalpha():
        if not word.isascii():
            return -0.4
        if text.startswith(' '):
            return 0.6 if len(word) <= 2 else -0.55
        frequency = zipf_frequency(word, 'en')
        if word[0].isupper():
            if frequency >= 6:
                return -0.5
            return 2.0 if frequency < 3 else 0.9
        return -0.6 if frequency < 3 else 0.3
    return 1.0


def background_level(text):
    if text == '<|im_start|>':
        return -0.09
    if text == '<|im_end|>':
        return -0.04
    if text.startswith(('<tool_', '</tool_')):
        return 0.11
    if text == '://':
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        level = opening_level(token)
        return (doc, token_id, token, True, 1, level), level
    _, first_id, first_text, uniform, count, level = carry
    same = uniform and token_id == first_id
    value = level if same else background_level(token)
    if count == 1 and first_text == 'Title' and token == ':':
        value = 10.0
    return (doc, first_id, first_text, same, count + 1, level), value

programs.haiku:
"""v4"""
import unicodedata

READS = ()


def script_of(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except ValueError:
        return "UNKNOWN"


def value_of(text):
    if text == "":
        return 0.0
    if "�" in text:
        return 1.5
    core = text.strip(" \t\r\n")
    if core == "":
        if "\n" in text or "\r" in text:
            return 0.9
        return 3.0 if len(text) == 1 else 4.5
    if "\n" in text or "\r" in text:
        last = text.rstrip(" \t\r\n")[-1:]
        if last in ";{[":
            return -2.7
        if last in ")]}:,":
            return -1.0
        if last in ".!?*>|":
            return 1.5
        return 0.3
    word = text.strip(" ")
    if word.isdigit():
        return -1.2
    if word.isascii() and word.isalpha():
        if word.isupper():
            return 0.3
        if word.islower():
            return -0.4
        return 0.9 if text[0] != " " else -0.5
    if all(not c.isalnum() for c in core):
        return 1.5 if core.isascii() else 0.9
    letters = [c for c in core if c.isalpha()]
    if not letters:
        return 0.5
    scripts = [script_of(c) for c in letters]
    top = max(set(scripts), key=scripts.count)
    if top == "LATIN":
        return 0.6
    if top == "CJK" or top in ("HIRAGANA", "KATAKANA", "HANGUL", "BOPOMOFO"):
        return 0.4
    if top == "CYRILLIC":
        return -0.5
    if top == "FULLWIDTH":
        return -1.1
    return 2.0


def step(carry, prefix, upstream):
    t = prefix.position
    first = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return carry, 0.0
    return carry, float(value_of(prefix.token_strings[-1]))

