"""Negative pulses for felt-sense phrases and related feeling morphemes.

English peaks at 'of' in 'a sense of'; 'make sense of' and 'in the
sense of' are much weaker. The same strong signal appears in 感,
Korean 감, and Vietnamese cảm (sense/feeling). Longer Han compounds
are weaker. A separate response covers increase/decrease vocabulary.
Other tokens default to zero. A three-token history resets by document.
"""
READS = ()

# Smaller English perceptual constructions, e.g. 'an impression of'.
PERCEPTUAL = {
    'impression', 'impressions', 'perception', 'perceptions',
    'sensation', 'sensations', 'touch', 'shade', 'shades',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, sense_mode = (), ''
    else:
        _, recent, sense_mode = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = recent[-1] if recent else ''
    value, next_mode = 0.0, ''

    if word == 'sense':
        if previous in {'make', 'makes', 'making', 'made'}:
            next_mode = 'understanding'
        elif recent[-2:] in {('in', 'the'), ('in', 'a')} or (
            len(recent) == 3 and recent[:2] == ('in', 'the')
        ):
            next_mode = 'meaning'
        elif previous in {'a', 'an'} or (
            previous in {'strong', 'general'} and recent[-2:-1] == ('a',)
        ):
            value, next_mode = -3.6, 'feeling'
        else:
            next_mode = 'other'
    elif word == 'of':
        if previous == 'sense':
            value = {
                'feeling': -12.3, 'understanding': -0.6,
                'meaning': -3.0, 'other': -8.5,
            }.get(sense_mode, -8.5)
        elif previous in {'feeling', 'feelings', 'senses'} or (
            ''.join(recent[-2:]) in {'feeling', 'feelings'}
        ):
            value = -6.2
        elif previous in PERCEPTUAL:
            value = -1.8
        elif previous == 'air':
            value = -3.5
        elif previous in {'layer', 'layers'}:
            value = -1.2
        elif previous == 'hint':
            value = -0.5
    elif word in {'感', '감', 'cảm'} or (
        word == 'm' and not token[0].isspace()
        and (previous == 'cả' or recent[-2:] == ('c', 'ả'))
    ):  # also the final token of a split Vietnamese 'cảm'
        value = -6.5
    elif word == '각' and previous == '감':  # completes 감각: sense
        value = -3.0
    elif word == '性感':  # sensual/sexy
        value = -3.6
    elif word.endswith('感'):  # compounds ending in the feeling character
        value = -1.8
    elif '感' in word:
        value = -0.6
    elif word in {'减', '減', 'giảm'}:  # decrease/subtract
        value = -3.0
        if previous in {'加', '增', '増'}:
            value = -7.0
    elif word in {'增', '増'}:  # increase
        value = -0.7
    elif word == '更加':  # even more
        value = -1.6

    return (doc, (recent + (word,))[-3:], next_mode), value

"""Lexical 'regardless/whether' cues, mostly Chinese.

Chinese unconditional expressions have the strongest negative response;
negation also amplifies their separately tokenized characters. English
'whether' is stronger at a clause boundary than in an embedded question.
Uncertainty words are negative; Chinese finality and doubled middle dots
are positive. Ordinary tokens are approximated by zero.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    previous = ''
    if (len(prefix.token_strings) > 1 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].rstrip()

    if word.lower() == 'whether':
        if word[0].isupper():
            value = -1.0
        elif previous.endswith((',', ';', '.', ':', '!', '?')):
            value = -0.95
        elif previous.strip().lower() in {'but', 'so', 'that'}:
            value = -0.6
        elif previous.strip().lower() in {'and', 'or'}:
            value = -0.35
        else:
            value = -0.18
    elif word.startswith(('无论', '無論', '不论', '不論', '不管')):
        if word.startswith('不管'):
            value = -9.5 if word == '不管' else -8.4
            if word.endswith(('你', '您')):
                value = -6.0
        elif word.startswith('无论'):
            value = -8.3 if word == '无论' else -7.2
        elif word in {'不论', '不論'}:
            value = -8.2
        else:
            value = -6.8
    elif word == '拘' and previous.endswith('不'):
        value = -7.2  # 不拘: without restriction
    elif word == '管':
        if previous.endswith('不'):
            value = -9.0
        elif previous.endswith('只'):
            value = -5.3
        elif previous.endswith(('儘', '尽')):
            value = -2.8
        # Physical tubes, and YouTube's Chinese nickname (oil + tube).
        elif previous.endswith(tuple('水风風气氣油钢鋼焊铜銅座温溫极極旋')):
            value = -0.4
        else:
            value = -3.2
    elif word in {'论', '論'}:
        if previous.endswith(('不', '无', '無')):
            value = -11.5
        elif previous.endswith('勿'):
            value = -4.8
        elif previous.endswith(('结', '結')):
            value = 0.0
        else:
            value = -1.2
    elif word in {'不知', '不知道'}:
        value = -2.45 if word == '不知' else -1.8
    elif word in {'到底', '究竟'}:
        value = -2.1
    elif word == '分辨':
        value = -2.5
    elif word in {'最后', '最后一', '到最后'}:
        value = 1.4
    elif word == '最後':
        value = 2.3
    elif word in {'最终', '最終'}:
        value = 0.9
    elif word == '史上最':
        value = 1.5
    elif word == '··':
        value = 1.29
    else:
        value = 0.0
    return None, value

"""Short pa/pad/pat/path spelling fragments, especially split just after p.

Transliteration also recognizes Greek and Cyrillic versions of these letters.
Closed ad/ath syllables following a separate p are strongest; a complete path
fragment is weaker. Long words merely containing pa are mostly ignored.
This is a spelling approximation, not a detector of the meaning of path;
context-dependent strengths and responses in other scripts are not modeled.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    for ch in text:
        if ch.isalpha() and not any(script in unicodedata.name(ch, '')
                                    for script in ('LATIN', 'GREEK', 'CYRILLIC')):
            return ''
    return anyascii(text).lower()


def fragment_value(token, previous):
    s = spelling(token)
    # A syllable completed across the immediately preceding token boundary.
    if previous.endswith('p') and s and s[0].isalpha():
        if s.startswith('ad'):
            tail = s[2:]
            if tail in ('', 's', 'a', 'i'):
                return 8.8
            if tail == 'e':
                return 4.5
            if tail in ('ded', 'ding'):
                return 5.8
            return 1.5
        if s.startswith('at'):
            tail = s[2:]
            if tail in ('h', 'ch'):
                return 7.3
            if not tail:
                return 6.0
            if tail in ('t', 's', 'i', 'ica'):
                return 4.1
            if tail == 'hs':
                return 5.1
            return 1.4 if len(s) <= 6 else 0.2
        if s == 'a':
            return 3.1
        if s.startswith('as') and len(s) <= 5:
            return 2.5
        if s in ('ab', 'ah', 'aw'):
            return 3.0
        if s.startswith('d'):
            return 3.0 / len(s)
        if s == 'h':
            return 0.9
        if s in ('o', 'op'):
            return -0.5
        if s.startswith('a'):
            return 0.4
    if previous.endswith('pas') and s == 'sed':
        return 1.8  # PAS + SED, a common split of PASSED.

    # Whole short fragments inside the current token.
    m = re.search(r'pa([a-z]*)$', s)
    if not m:
        return 0.0
    tail = m[1]
    before = s[:m.start()]
    if s in ('opath', 'opathy'):
        return 7.5 if s == 'opath' else 4.8
    if tail in ('d', 'ds'):
        value = 6.0
    elif tail == 'da':
        value = 4.3
    elif tail in ('dding', 'dded'):
        value = 2.8
    elif tail == 't':
        value = 4.4
        if any(c.isupper() for c in token):
            value *= 0.65
    elif tail in ('th', 'ths'):
        value = 2.4
        if before.isspace():
            value *= 0.75
        elif before == '.':
            value *= 0.45
        elif before in ('_', '('):
            value *= 0.65
    elif tail == 'tch':
        value = 5.5 if not before else 2.4
    elif tail in ('thway', 'thways', 'ttern', 'tterns'):
        value = 0.55
    elif tail == '':
        value = 1.6 if not before else 1.0
    elif tail in ('s', 'ss', 'st', 'ste'):
        value = 0.8 if tail == 'ste' else 0.3
    else:
        return 0.0
    # A longer piece before the syllable weakens it (iPad, keypad, filepath).
    letters_before = sum(c.isalpha() for c in before)
    return value * (0.6 ** letters_before)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = fragment_value(token, previous)
    return (document, spelling(token)), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:5347, as a "pad / pat / path" spelling detector.

It fires on the "a" of "pa" when that "a" is typed inside a word, and more strongly
on the letters that follow it:
  "pad"  (odpad, Pad, pads, padx)            strongest, about 6
  "pat", "path", "patch" (word ends or h/c)  moderate, about 2
  "pa" by itself at the end of the word      about 1
  "patt" (pattern), "pas" (pass)             weak, about 0.3 to 0.5
Everything else is 0. The word may be split across tokens (a "p" token followed by
an "ad" token), and Cyrillic or Greek letters that look alike (п, а, д, т; π, α) count
too, so "зап"+"ад" is "запад". Words separated by a space do not join ("IP address"
is not "ipaddress").

Predicted value: the largest response among the "pa" completed by the current token.
"""

import re

READS = ()

# Cyrillic and Greek letters that look like p, a, d, t
LOOKALIKE = str.maketrans({"п": "p", "π": "p", "а": "a", "α": "a", "ά": "a", "д": "d", "т": "t"})

LETTERS = r"[^\W\d_]*"


def normal(letters):
    return letters.translate(LOOKALIKE).lower()


def response(run, start):
    """Largest response to a "pa" in run whose "a" is at or after index start."""
    best = 0.0
    for j in range(len(run) - 1):
        if run[j : j + 2] != "pa" or j + 1 < start:
            continue
        after = run[j + 2 :]  # the letters after "pa"
        if after.startswith("d"):
            value = 6.0
        elif after.startswith("t"):
            if after[1:2] in ("h", "c", ""):
                value = 2.0  # pat, path, patch
            else:
                value = 0.5  # patt... (pattern, patter)
        elif after == "":
            value = 1.1  # the word ends in "pa"
        elif after.startswith("s"):
            value = 0.3  # pas, pass
        else:
            value = 0.0
        best = max(best, value)
    return best


def step(carry, prefix, upstream):
    t = prefix.position
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.text_prefixes[t - 1][-12:] if same_doc else ""
    now = prefix.text_prefixes[t]
    if same_doc and now.startswith(prefix.text_prefixes[t - 1]):
        cur = now[len(prefix.text_prefixes[t - 1]) :]
    else:
        cur = prefix.token_strings[-1]
    # the word being typed: letters before this token, then the letters this token starts with
    word = normal(re.search(LETTERS + "$", before).group(0))
    lead = re.match(LETTERS, cur).group(0)
    if lead:
        run, start = word + normal(lead), len(word)
    else:
        found = re.search(r"[^\W\d_]+", cur)
        run, start = (normal(found.group(0)) if found else ""), 0
    return carry, response(run, start)

programs.sol:
"""An opening-token pulse, especially for numbers and whitespace.

The pulse lasts through repetitions of the opening token; an opening run of
1s can also extend into 2s, at reduced strength. A different token normally
ends it. Pulse size is estimated from digits, whitespace and punctuation.
For ASCII words, common English words get a negative pulse and less common
ones a small positive pulse. Word-specific differences and small later
activations are ignored; state resets at each document boundary.
"""
from wordfreq import zipf_frequency

READS = ()

DIGITS = (11.63, 6.75, 11.19, 11.01, 11.50,
          10.33, 12.07, 11.90, 11.73, 4.75)
WHITESPACE = {
    ' ': 3.82, '  ': 8.37, '   ': 5.23,
    '\t': 8.71, '\n': 5.62, '\n\n': 3.41,
}


def opening_pulse(s):
    w = s.strip()
    if len(s) == 1 and s in '0123456789':
        return DIGITS[int(s)]
    if s.isspace():
        return WHITESPACE.get(s, 4.0)
    if s == '<|endoftext|>':
        return 10.0
    if s.startswith('<|'):
        return -0.5
    if w in {r'\n', r'\t'}:
        return -2.5
    if w.isascii() and w.isalpha():
        frequency = zipf_frequency(w, 'en')
        return 0.6 if frequency < 5 else 0.0 if frequency < 6 else -0.9
    if any(c.isalnum() for c in s):
        return 0.5

    # Grouping delimiters, operators, and sentence punctuation.
    if w == '|':
        return 8.45 if s.startswith(' ') else 3.85
    if w == '-' and s.startswith(' '):
        return 6.0
    if w == '//':
        return 4.6
    if w == '{':
        return 4.0
    if w.startswith('(') and ')' not in w:
        return 2.5
    if w == '[':
        return 3.0
    if w in {'"', "'", '“'} and s.startswith(' '):
        return 2.1
    if w in {'=', '+', '*', '<', '>', '$'}:
        return 3.0 if s.startswith(' ') else 2.0
    value = -0.8 if w in {',', '，', '。', "'", '”'} else 0.2
    if '\n' in s:
        value += 0.5 if '\n\n' in s else 1.5
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening_pulse(s)
    else:
        _, previous, value = carry
        if token != previous:
            extends_number = previous == b'1' and token == b'2' and value > 6
            value = 9.6 if extends_number else 0.0
    return (doc, token, value), value

programs.haiku:
"""Component layers.1.mlp.down_proj:5348: a "document opener" detector.

The component is silent almost everywhere. Its activity is concentrated on the first token of
each document (a row's first token, or the first token after `<|endoftext|>` where the document
id changes), and there it depends only on which token opens the document:

- a digit 0-9 opens the document: strongly positive (about 11; "1" about 7, "9" about 5);
- a whitespace-only token (newline, tab, indentation), a time or date word ("Today",
  "Tuesday", "December", "Next", "When"), or a code/comment opener ("//", "/*", "#include",
  "{", "|", "=", "(") or a code keyword ("package", "import", "const", "def"): moderately
  positive (about 4-5);
- a common function word ("The", "the", "a", "of", "to", "is", "was", "This", ...): slightly
  negative (about -1.5);
- any other token: about 0.

At the document's second token, if it repeats a digit that opened the document (as in "00" or
"77"), it takes that digit's value. Everywhere else it is 0.

The program carries only the count of tokens since the document started, and the document's
first token, so it resets at each document boundary as the model does.
"""

DIGITS = "0123456789"
FUNCTION_WORDS = frozenset(
    "the a an of to and in is was it that with for as on by be at or from this i they we he "
    "she you are were not but if its his her has have had which who when than then there here "
    "so do does".split()
)
TIME_WORDS = frozenset(
    "today yesterday tomorrow now next recently currently monthly when whenever if monday "
    "tuesday wednesday thursday friday saturday sunday january february march april may june "
    "july august september october november december".split()
)
CODE_OPENERS = frozenset(["//", "/*", "/*\n", "#include", "{", "|", " |", "=", " =", "(", " (", '"', " -"])
CODE_WORDS = frozenset("package import const export def class return function var let".split())

READS: tuple[str, ...] = ()


def opener_value(token: str) -> float:
    """The component's value when this token is the first token of a document."""
    if len(token) == 1 and token in DIGITS:
        return {"1": 7.0, "9": 5.0}.get(token, 11.0)
    if token and token.strip() == "":
        return 5.0
    word = token.strip().lower()
    if word in TIME_WORDS:
        return 5.0
    if word in FUNCTION_WORDS:
        return -1.5
    if word in CODE_WORDS:
        return 4.0
    if token in CODE_OPENERS or token.startswith(("//", "/*", "#include")):
        return 4.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        index, first = 0, token
    else:
        index, first = carry[0] + 1, carry[1]
    if index == 0:
        value = opener_value(token)
    elif index == 1 and token == first and len(token) == 1 and token in DIGITS:
        value = opener_value(first)
    else:
        value = 0.0
    return (index, first), value

"""Post-noun modifier opener (layers.1.mlp.down_proj:5349).

The component goes negative on a token that opens a modifier of a noun that was just
written: a relative word ("the people WHO", "the countries THAT", "the matter IN WHICH"),
a subject pronoun starting a reduced relative clause ("the spirit IT represents"), a place
word ("the graph BELOW", "the material ON this website"), a past participle ("the data
RECORDED"), or "the" inside a phrase such as "the number OF THE" (weaker, -0.25, when "the" follows a preposition such as of, from or
between). The strongest cases follow a definite noun phrase; a bare noun gives a small
value, and "a/an" gives zero.
Everywhere else it predicts 0.
"""

READS = ()

RELATIVE = {" who", " which", " that", " where", " whose", " whom", " when"}
SUBJECT = {" I", " you", " we", " they", " he", " she", " it"}
PLACE = {" below", " above", " after", " under", " around", " within", " before",
         " inside", " behind", " between", " in", " on", " at", " from"}
DEFINITE = {" the", " this", " these", " those", " its", " their", " his", " her", " my", " our", " your"}
INDEFINITE = {" a", " an"}
FUNCTION = {
    "the", "a", "an", "of", "and", "or", "to", "in", "on", "at", "for", "with", "by", "from",
    "is", "are", "was", "were", "be", "been", "being", "as", "that", "which", "who", "not",
    "it", "this", "these", "those", "its", "their", "his", "her", "he", "she", "they", "we",
    "you", "i", "there", "so", "but", "if", "then", "than", "also", "can", "will", "has",
    "have", "had", "do", "does", "did", "into", "about", "over", "under", "my", "our", "your",
}
# Strength of the opener, after a definite noun phrase and after a bare noun.
STRONG = {"relative": 1.2, "subject": 1.2, "place": 0.75, "participle": 0.45, "the": 0.45}
BARE = 0.15
AFTER_PLACE = {" of", " between", " after", " from", " inside", " around", " before", " in", " by", " and"}


def _is_content_word(s):
    """A letters-only token that is not a function word: a noun or adjective, roughly."""
    w = s.strip()
    return w.isalpha() and w.lower() not in FUNCTION


def _kind(s):
    if s in RELATIVE:
        return "relative"
    if s in SUBJECT:
        return "subject"
    if s in PLACE:
        return "place"
    if s == " the":
        return "the"
    if s.strip().endswith(("ed", "en")) and s.strip().isalpha():
        return "participle"
    return None


def _definite_before(prefix, t):
    """Whether a definite determiner sits 2 or 3 tokens back, in the same document."""
    for back in (2, 3):
        i = t - back
        if i < 0 or prefix.document_ids[i] != prefix.document_ids[t]:
            return False
        if prefix.token_strings[i] in DEFINITE:
            return True
        if prefix.token_strings[i] in INDEFINITE:
            return False
    return False


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    if t < 1 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, 0.0
    kind = _kind(cur)
    if kind is None or not _is_content_word(prefix.token_strings[t - 1]) and kind != "the":
        return carry, 0.0
    if _definite_before(prefix, t):
        return carry, -STRONG[kind]
    if kind == "the" and prefix.token_strings[t - 1] in AFTER_PLACE:
        return carry, -0.25
    if kind == "the" or not _is_content_word(prefix.token_strings[t - 1]):
        return carry, 0.0
    return carry, -BARE * STRONG[kind]

programs.sol:
"""A surface-rule approximation for conditional wording and formatting.

Prose conditional 'if' is positive; 'if' after an embedded-question verb
(check, see, know...) or at an indented code-line start is suppressed.
Translated conditional forms use a word-frequency-based language guess.
Mixed indentation, written-out newlines, 'going to', calendar ordinals,
and a few text-formatting markers supply the other positive responses.
TeX-like line breaks and an initial lone tab are negative.
Unrecognized cases predict zero.

Only a 160-character text tail is retained, reset at document boundaries.
"""
import re
import calendar
import wordnet
from wordfreq import zipf_frequency

READS = ()
MONTH = '|'.join(calendar.month_name[1:] + calendar.month_abbr[1:])
DATE_END = re.compile(r'\b(?:' + MONTH + r')\.?\s+\d{1,2}$', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    s = prefix.token_strings[-1]
    word = s.strip()
    lower = word.lower()
    line = re.split(r'\n|\\n', tail)[-1]
    value = 0.0

    # Whitespace used for horizontal layout, rather than ordinary word spacing.
    if s and not s.strip(' \t'):
        spaces = s.count(' ')
        tabs = s.count('\t')
        if not tail:
            value = -2.7 if s == '\t' else 0.0
        elif tabs and spaces:
            value = (0.75 if spaces <= 4 else
                     1.35 if spaces <= 8 else
                     1.2 if spaces <= 12 else 1.65)
            if s.startswith(' '):
                value = 2.4 if tail.endswith('\t') else 0.9
        elif tabs:
            value = (1.9 if tail.endswith(' ') else
                     -0.07 if tail[-1:].isspace() else 0.3)
        elif tail.endswith('\\n'):
            value = (1.7 if spaces == 1 else
                     0.65 if spaces in (3, 5) else 0.35)
        elif re.search(r'''(?:print|log)\([fb]?["']$''', tail):
            value = 1.5 if spaces == 1 else 0.5
        elif tail.endswith('\t'):
            value = 1.65 if spaces >= 4 else 0.0
        elif tail.endswith('\n'):
            value = 0.75 if spaces == 1 else 0.0
        elif 2 <= spaces <= 5:
            value = 0.15

    # A tab attached to a word can continue a mixed indentation run.
    elif s.startswith('\t') and tail.endswith(' '):
        value = 1.8
    elif lower == 'if':
        boundary = s[:1].isspace() or not tail or not tail[-1].isalnum()
