            if word.islower() and (not line.strip() or
                                   re.fullmatch(r'[ \t+\-]*\d*[ \t]*', line) or
                                   re.search(r'\belse\s*$', line)):
                value = -0.2
            elif s.startswith('\t'):
                value = 0.12
            elif word == 'IF':
                value = 0.25
            else:
                value = 1.0 if s.startswith(' ') else 0.8
                previous = re.findall(r'[A-Za-z]+', tail[-25:])
                last = previous[-1].lower() if previous else ''
                roots = set(wordnet.base_forms(last)) | {last}
                question_verbs = {'check', 'see', 'know', 'determine', 'wonder',
                                  'ask', 'tell', 'verify', 'decide', 'ascertain'}
                if roots & question_verbs or last in ('sure', 'unsure', 'as'):
                    value = 0.0
                elif last == 'only':
                    value = 0.45
                elif last == 'or':
                    value = 0.65
    elif lower in ('se', 'si') and not word.isupper():
        # The same spelling is an unrelated pronoun in other languages.
        words = re.findall(r'[^\W\d_]+', tail.lower())[-12:]
        if words and (s[:1].isspace() or not tail[-1:].isalnum()):
            languages = ('en', 'fr', 'es', 'it', 'pt', 'de', 'cs', 'pl', 'ro', 'tr')
            language = max(languages, key=lambda lang: sum(
                zipf_frequency(w, lang) for w in words))
            if lower == 'se' and language in ('it', 'pt'):
                value = 1.9 if language == 'it' else 1.4
            elif lower == 'si' and language in ('es', 'fr'):
                value = 1.6
    elif word == '如果':
        value = 0.9
    elif word == '若':
        value = 0.65
    elif lower == 'если' or (tail + s).lower().endswith('если'):
        value = 1.5
    elif s == ' to' and re.search(r'\bgoing$', tail):
        value = 1.25
    elif lower == 'gonna':
        value = 1.5
    # Formatting: calendar ordinals, indented code markup, and escaped text.
    elif lower in ('st', 'nd', 'rd', 'th') and DATE_END.search(tail):
        value = 1.4
    elif s == '``' and tail.endswith('\xa0'):
        value = 1.0
    elif s.strip() == '\\\\':
