            value = 0.6
        elif re.search(r'\\[A-Za-z]+', tail):
            value = -1.0
    elif s == '](' or (s == '#' and tail.endswith('](')):
        value = 1.3

    return (doc, (tail + s)[-160:]), value

"""Bed/floor/bottom vocabulary, not a general detector of lower positions.

The largest English responses are compound beds and sea floors. Testbed
mentions weaken with repetition. Chinese bottom/end words, the characters
for bed, resist and top, and two Thai spellings are additional triggers.
Most tokens get zero; document starts have a small positive baseline.
"""
import math
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        count, previous, tail = 0, '', b''
    else:
        _, count, previous, tail = carry
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    joined = (tail + raw)[-64:]
    # Recover a character whose UTF-8 bytes straddle token boundaries.
    if text == '\ufffd':
        decoded = joined.decode('utf-8', errors='ignore')
        if decoded and joined.endswith(decoded[-1].encode('utf-8')):
            text = decoded[-1]
    context = tail.decode('utf-8', errors='ignore').lower()
    word, prior = text.strip().lower(), previous.strip().lower()
    value = 0.16 if first else 0.0

    if text == 'bed' and prior.endswith('test'):
        value = -5.0 - 1.24 / math.sqrt(count + 1)
        count += 1
    elif text == 'bed' and prior in {'river', 'stream', 'sea'}:
        value = -9.5
    elif text == 'bed' and prior in {'road', 'foot', 'hot', 'seed', 'flower'}:
        value = -5.0
    elif word in {'bed', 'beds', '_bed', '-bed'}:
        # An internal fragment such as the end of 'probed' is much weaker.
        value = -2.3 if word.endswith('beds') else -1.5
        if text == 'bed':
            value = -0.4 if previous[-1:].isalpha() else -2.5
            if first:
                value = -3.7
        if word.startswith(('_', '-')):
            value = -2.5
        if prior in {'river', 'sea', 'sofa'} or context.endswith("river's"):
            value = -6.0
        elif prior in {'raised', 'flower', 'fluid', 'fluidized', 'fixed'}:
            value = -3.8
    elif word in {'floor', 'floors', 'loor'}:
        value = -1.0 if text.startswith(' ') or word == 'loor' else -0.2
        if prior in {'sea', 'ocean'} or context.endswith('seaf'):
            value = -9.4
        elif prior == 'forest':
            value = -5.2
        elif prior == 'ground':
            value = -2.7
        elif prior in {'first', 'second', 'third', 'fourth', 'top', 'upper'}:
            value = -0.4
    elif text.endswith('底'):
        value = -7.3 if text == '到底' else -6.1
    elif text == '抵':
        value = -5.5
    elif text == '床':
        value = -3.1
    elif text in {'顶', '頂'}:
        value = -1.9
    elif text.startswith('究竟'):
        value = -4.2
    elif text in {'年末', '期末'}:
        value = -2.3
    elif text == '到底是':
        value = -4.0
    elif text in {'底部', '底下'}:
        value = -1.8
    elif previous in {'底', '抵'} and regex.fullmatch(r'\p{Script=Han}', text):
        value = -1.8
