    elif text == 'ถ':
        value = -5.3
    elif text == 'ี' and previous.endswith('ด'):
        value = -5.0

    return (doc, count, text, joined), value

"""An Italian word-piece feature, with a short memory of language.

Compare dictionary frequencies in Italian with five neighboring/common
languages. A partial word inherits the frequency of its most frequent
completion. Recent complete words provide a decaying language cue.
Italian-looking fragments get positive values; punctuation is usually quiet,
but apostrophes in Italian context are strong. The small decision tree below
was fitted on these spelling/frequency concepts, not on token identities.
"""
from functools import lru_cache
import re
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('it', 'en', 'es', 'fr', 'pt', 'de')
CONJUNCTIONS = set('e o ma che anche oppure se mentre perché quando quindi'.split())


@lru_cache(maxsize=1)
def prefix_dictionaries():
    italian, others = {}, {}
    for language in LANGUAGES:
        table = italian if language == 'it' else others
        for word in top_n_list(language, 50000):
            if not word.isalpha():
                continue
            frequency = zipf_frequency(word, language)
            for length in range(1, len(word) + 1):
                part = word[:length]
                table[part] = max(table.get(part, 0.), frequency)
    return italian, others


@lru_cache(maxsize=200000)
def familiarity(word):
    if not word or not word.isalpha():
        return 0., 0., 0., 0.
    italian, others = prefix_dictionaries()
    return (italian.get(word, 0.), others.get(word, 0.),
            zipf_frequency(word, 'it'),
            max(zipf_frequency(word, lang) for lang in LANGUAGES[1:]))


def bounded_difference(a, b):
    return max(-4., min(4., a - b))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., 0.)
    _, word, context, previous = carry
    boundary = not text[:1].isalpha() or not word
    if boundary and word:
        _, _, italian, other = familiarity(word)
        previous = bounded_difference(italian, other)
        context = .55 * context + .45 * previous
        word = ''
    chunks = re.findall(r'[^\W\d_]+', text.lower())
    fragment = chunks[-1] if chunks else ''
    word = (word + fragment) if text[:1].isalpha() else fragment
    word = word[-40:]
    ip, op, iw, ow = familiarity(word)
    prefix_advantage = bounded_difference(ip, op)
    word_advantage = bounded_difference(iw, ow)
    quote = text.strip() in ("'", '’')
    carry = doc, word, context, previous

    if context <= .5:
        if prefix_advantage > 3.:
            value = .35017 if word_advantage <= 2.5 else 1.14768
        elif context < -.0004:
            value = -.00149
        elif op <= 3.58:
            value = .01049
        else:
            value = .76413 if previous <= -.03 else .26916
    elif ip == 0.:
        if quote:
            value = 2.59050
        else:
            value = .09033 if word_advantage <= .25 else 1.12525
    elif word_advantage > 2.:
        value = .94601
    elif ip <= 4.335:
        value = .51326 if prefix_advantage <= -.215 else 1.12939
    elif iw <= 4.335:
        value = 1.74549
    else:
        value = .60369 if word in CONJUNCTIONS else 1.26374
    return carry, value

"""Local approximation to definitional and biographical description cues.

Articles after copulas, birth notes, nationalities, classification/location
nouns, and their linking words are positive. Ordinary relative 'which' is
negative. Shell flags are a separate positive cue. Unrecognized patterns are
zero; sixteen recent tokens supply context, reset at each document boundary.
The short noun-phrase window approximates the continuation of a definition;
its scores are rounded training estimates, not a reconstruction of the model.
"""
import re

READS = ()

NATIONALITIES = set((
    'American English Indian British Russian Scottish German French Italian '
    'Canadian Australian Spanish Japanese Chinese Irish Welsh Polish Swedish '
    'Norwegian Danish Dutch Belgian Swiss Austrian Finnish Greek Portuguese '
    'Turkish Korean Brazilian Mexican Argentine Ukrainian Romanian Hungarian '
    'Czech Slovak Croatian Serbian Bulgarian Iranian Israeli Egyptian African '
    'Nigerian Pakistani Bangladeshi Indonesian Malaysian Singaporean Vietnamese '
    'Thai Filipino'
).split())
TAXA = set('species genus family order class subspecies'.split())
TYPES = set((
    'process method practice branch system mechanism technique procedure form '
    'type kind group set collection series unit measure field study way act '
    'part member tool model function equation definition'
).split())
PLACES = set((
    'city town village municipality district county province region state '
    'island river lake mountain settlement'
).split())
JOBS = set((
    'player football footballer actor actress artist writer politician singer '
    'composer scientist professional retired former'
).split())
COPULAS = set('is was are were am be been being'.split())
PRONOUNS = set('it he she we they you i this that there what'.split())
COMMANDS = set((
    'grep egrep rg head tail cat sed awk python python3 node curl wget git ls '
    'find sort cut wc diff yarn npm pip bash'
).split())
RELATIONS = {
    'refers to': 2.2,
    'referred to': .5,
    'used to': .4,
    'method to': .6,
    'known as': .8,
    'defined as': 1.5,
    'also known': 1.7,
    'also called': 1.5,
    'located in': .2,
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    old = carry[1] if carry is not None and carry[0] == doc else []
    s = prefix.token_strings[-1]
    word, w = s.strip(), s.strip().lower()
    h = [x.strip().lower() for x in old]
    p = h[-1] if h else ''
    subject = old[-2].strip() if len(old) > 1 else ''
    v = .1 if s.startswith(' ') and w in {'that', 'who', 'when', 'also'} else 0.
    if w == 'born':
        v += 3.2 if s == 'born' and '(' in p else .5
    if w == 'located':
        v += .0 if p in {'be', 'been', 'being'} else .5 if p in COPULAS else 1.2
    if w in {'refers', 'means', 'used'}:
        v += 1.6 if w == 'refers' else .3
    if s in {' States', ' sports', ' entity'}:
        v += .95
    if s == ' territorial':
        v += .55

    # Distinguish named/topic definitions from 'it/there/this is a ...'.
    if w in {'a', 'an', 'the'} and s.startswith(' ') and p in COPULAS:
        v += .2 if w != 'the' else .4
        if subject.lower() in PRONOUNS:
            v -= .6 if w != 'the' else .2
        elif ')' in subject or ']' in subject:
            v += 1.2 if w != 'the' else .3
        if w != 'the':
            before = ''.join(old[:-1])
            if re.search(r"[A-Z][A-Za-z'-]*$", before):
                if subject.lower() not in PRONOUNS | {'who', 'which'}:
                    v += .4
            v += .8 if ',' in subject else 0.
            v += .8 if 'born' in h else 0.
            if any(c in before for c in '$=\\_'):
                v -= .5

    # A defining noun phrase lasts at most six following tokens here.
    defining = False
    for k in range(1, min(7, len(h))):
        if h[-k] in {'a', 'an', 'the'} and h[-k-1] in {'is', 'was', 'are', 'were'}:
            between = h[-k+1:] if k > 1 else []
            if not any(c in t for t in between for c in '.;!?'):
                defining = True
                break
    if word in NATIONALITIES:
        v += .6 if word == 'American' else .1
        if p in {'a', 'an'}:
            v += 1.8 if word == 'American' else .6
        if defining:
            v += 2.2 if word == 'American' else 1.1
    if defining:
        if w in TAXA | TYPES:
            v += 1.8 if w == 'genus' else .5
        elif w in PLACES | JOBS:
            v += .95
        if w in {'that', 'which', 'who', 'by', 'used'}:
            v += 1. if w in {'that', 'used'} else .8

    v += RELATIONS.get(p + ' ' + w, 0.)
    if w == 'of':
        if p in TAXA:
            v += 2.8 if p == 'genus' else 1.1 if p == 'species' else 0.
        elif p in {'branch', 'field', 'study', 'unit', 'measure'}:
            v += .65
        elif p in {'process', 'practice', 'act', 'method', 'way'}:
            v += .4
        elif p in TYPES:
            v += .15
        if p == 'instance':
            v += .5
        if defining and p in TAXA | TYPES:
            v += .9
    if w == 'by' and p in {'written', 'song', 'album', 'directed', 'produced'}:
        v += 1.
    if w == 'in' and p in PLACES:
        v += .65
    if w == 'who' and p in JOBS | {'er'}:
        v += 1.6
    if w == 'which':
        v -= .8 if ',' in p else .45
        if p in {'in', 'for', 'of', 'to', 'from', 'with', 'on', 'at', 'by'}:
            v += 1.1 if p == 'by' else .3
    if s == ' --':
        v += .65
    if s == ' -' and (p in COMMANDS or subject.lower() in COMMANDS):
        v += 1.15
    return (doc, (old + [s])[-16:]), float(v)

"""A negative response to word-internal 'nd', including transliterated spellings.

The strongest cases are n followed by d in a new token and short continuations
of a word ending in nd. Familiar whole words (especially 'and') respond little.
English word frequency softens whole-word responses; fragment length and
case distinguish short internal pieces from longer, often complete words.
The state holds the current spelling and any unfinished UTF-8 character.
"""
import codecs
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=40000)
def romanize(text):
    return anyascii(text).lower()


@lru_cache(maxsize=50000)
def frequency(word):
    return zipf_frequency(word, 'en')


def response(old, raw, s, word):
    fragment = s.strip()
    size = len(fragment)
    nd = s.rfind('nd')
    if old.endswith('n') and s.startswith('d'):
        if frequency(word) > 0.5:
            return -2.75
        if len(old) <= 6:
            return -2.24 if size <= 2 else -0.49
        return -0.32 if len(old) <= 9 else -0.054

    if nd >= 0:
        if not old:
            if frequency(word) > 5.42:
                return 0.0
            if size <= 4:
                return -0.96 if frequency(fragment) <= 3.35 else -0.32
            return -0.20 if size <= 6 else -0.10
        if nd <= 1:
            if raw.istitle():
                return 0.0
            return -1.47 if len(s) - nd - 2 <= 2 else -0.27
        if size <= 4:
            return -0.88 if frequency(fragment) <= 4.83 else -0.55
        return -0.32 if len(old) <= 4 else -0.057

    if old.endswith('nd'):
        if size <= 2:
            return -2.33 if frequency(fragment) > 7.0 else -1.03
        return -0.53 if size == 3 else -0.25
    return -0.025


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, pending = carry[1:] if carry and carry[0] == doc else ('', b'')
    decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    decoder.setstate((pending, 0))
    raw = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    if not raw:
        return (doc, old, pending), -0.001
    raw = raw.replace('\\n', ' ').replace('\\r', ' ').replace('\\t', ' ')
    if raw.startswith('<|') and raw.endswith('|>'):
        return (doc, '', pending), -0.001
    s = romanize(raw)
    if not re.match('[a-z]+', s):
        old = ''
    tail = re.search('[a-z]+$', old + s)
    word = tail.group()[-40:] if tail else ''
    active = 'nd' in s or old.endswith('n') and s.startswith('d')
    active = active or 'nd' in old and bool(re.match('[a-z]+', s))
    value = response(old, raw, s, word) if active else -0.001
    return (doc, word, pending), value

programs.haiku:
"""Layer-1 MLP output unit 5356: a dip on "n-d" letter pairs inside words.

The unit goes negative on pieces of a word whose letters contain n followed by d. Such words
are typically names and loanwords split into several tokens:
  Ashwag|and|ha, Ber|nd|t, Mand|r|ake, Mend|es, AN|DB, Lyn|d|eborough.
For a piece that continues a word (no leading space) and where the word so far contains "nd":
- base dip of -0.4;
- a further -0.4 when the piece itself carries the "nd" (and, end, nd, und, ind);
- a further -0.5 when the piece is very short (1-2 letters);
- the dip is removed for a capitalised piece (+0.5), so mid-name capitals stay near zero.
A word-initial piece with leading space that contains "nd" and is not an ordinary English
word gets -0.4 if it is short and -0.15 otherwise (" Mend", " Sund"; common words such as
" and" and " find" stay at zero). A single piece with no earlier piece of its word does not
count. Everywhere else it predicts 0.
"""
READS = ()

COMMON_ND_WORDS = {" and", " And", " AND", " end", " find", " around", " found", " hand",
                   " under", " second", " kind", " friend", " land", " wind", " stand",
                   " bind", " band", " behind", " send", " mind", " round", " ground",
                   " bound", " fund", " brand", " spend"}


def _word_so_far(prefix):
    """The current word's pieces, from its first piece (the one with a leading space,
    if any) through the newest token. Stops at a document change or a non-letter piece."""
    pieces = [prefix.token_strings[-1]]
    i = len(prefix) - 2
    while i >= 0 and prefix.document_ids[i] == prefix.document_ids[-1]:
        head = pieces[0]
        if head[:1] in (" ", "\n", "\t") or not head.isalpha():
            break
        pieces.insert(0, prefix.token_strings[i])
        i -= 1
    return pieces


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    pieces = _word_so_far(prefix)
    word = "".join(pieces).lower()
    if "nd" not in word:
        return carry, 0.0
    if cur[:1] not in ("", " ", "\n", "\t") and cur.isalpha() and len(pieces) > 1:
        value = -0.4
        if "nd" in cur.lower():
            value -= 0.4
        if len(cur) <= 2:
            value -= 0.5
        if cur[:1].isupper():
            value += 0.5
        return carry, value
    if cur.startswith(" ") and cur[1:].isalpha() and cur not in COMMON_ND_WORDS:
        return carry, (-0.4 if len(cur) <= 4 else -0.15)
    return carry, 0.0

programs.sol:
"""A modern-year-prefix detector, with smaller URL and address responses.

The main trigger is 19 or 20 at the start of a digit string. Calendar words
and temporal prepositions strengthen it; arithmetic contexts weaken it.
Continued numbers are suppressed. Only already-seen text is used.
Additional rules cover Chinese year prefixes, addresses, GitHub paths, patch
headers and document-opening Title: metadata.
"""
import calendar
import re
import regex

READS = ()
MONTHS = {s.lower() for s in calendar.month_name if s}
MONTH_PATTERN = r'\b(?:' + '|'.join(MONTHS) + r')\b'
TIME = set('in since during before after until from between early late mid '
           'circa year years born copyright'.split())
ARTICLES = {'a', 'an', 'the'}
QUANTITY = set('about approximately around nearly over under than least '
               'most exactly total only just every each'.split())
COPULA = set('is was are were be being equals equal'.split())
RELATION = set('and or to at with'.split())
PREPOSITIONS = set('of by for as'.split())


def year_strength(before, old):
    # Spelling, layout and preceding word indicate how year-like 19/20 is.
    c = before[-1:]
    value = 1.04 + .15 * old
    if c == ' ':
        match = re.search(r'([^\W\d_]+) +$', before)
        value += .18 if match else .26
        word = match[1].lower() if match else ''
        if word in TIME:
            value += .92 + .07 * old
        elif word in ARTICLES:
            value += .71 + .19 * old
        elif word in MONTHS:
            value += .70 + .03 * old
        elif word in QUANTITY or word in COPULA:
            value -= .63
        elif word in RELATION:
            value += -.41 + .15 * old
        elif word in PREPOSITIONS:
            value += -.15 + .43 * old
        if not word:
            if re.search(MONTH_PATTERN + r'[^a-zA-Z]*$', before.lower()):
                value += .70
    elif c == '(':
        value += .1 + .77 * before.endswith(' (')
    elif c and c in '\n\r':
        value += .16
    elif c == '/':
        value += .35
    elif c and c in ',:':
        value -= .13
    elif regex.search(r'\p{Script=Han}$', before):
        value += .63 + .63 * (c in '在于至到自从')
    elif c and c in '。，：、（':
        value += .79
    if re.search(r'[$€£¥₹] *$', before):
        value -= .4
    if re.search(r'\d[^\d\w]*$', before):
        value -= .42
    if re.search(r'\bet al[., ]*$', before, re.I):
        value += 1.28
    if re.search(r'© *$', before):
        value += .79
    # Numbers embedded in equations, code or numeric tables are less year-like.
    recent = before[-100:]
    if re.search(r'(?:[+*=<>×÷]| -) *$', before):
        value -= .37
    if sum(recent.count(c) for c in '=+*^×÷') >= 2:
        value -= .45
    if re.search(r'[;{}]|!=|==|:=|=>', recent):
        value -= .21
    tail = before[-80:]
    if sum(c.isdigit() for c in tail) > .2 * max(1, len(tail)):
        value -= .19
