    tok = prefix.token_strings[-1]
    word_so_far, prev_word = carry if carry is not None else ("", "")
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        word_so_far, prev_word = "", ""
    letters = "".join(c for c in tok if c.isalpha()).lower()
    new_word = tok[:1] == " " or not tok[:1].isalpha()
    if new_word:
        if word_so_far:
            prev_word = word_so_far
        word_so_far = letters
    else:
        word_so_far += letters
    value = 0.0
    if tok == "··" and prefix.token_strings[-2:-1] == ["··"]:
        value = -0.9
    elif "<think>" in tok or "</think>" in tok:
        value = 0.0
    elif "think" in word_so_far and letters and "think" not in word_so_far[: -len(letters)]:
        if not new_word:
            value = -9.5
        elif letters != "think":
            value = -4.7
        elif prev_word in PRONOUNS:
            value = -3.0
        elif prev_word in SETUP:
            value = -9.0
        else:
            value = -6.0
    elif "denk" in word_so_far and letters and "denk" not in word_so_far[: -len(letters)]:
