The main response is negative at the end of a chat message, weaker after
closing a tool call or response. Its magnitude grows with context length.
Other closing control tags have smaller responses. The initial Title: colon
has a strong positive response. Other text is approximated by zero.
"""
from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    n = carry[1] + 1 if carry is not None and carry[0] == doc else 1
    state = (doc, n)
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if n > 1 else ''

    if token == '<|im_end|>':
        if previous == '</tool_call>':
            value = -2.09 + 1.76 / sqrt(n)
        elif previous == '</tool_response>':
            value = -2.11 + 1.18 / sqrt(n)
        else:
            value = -2.57 + 0.78 / sqrt(n)
    elif token == '</think>':
        value = -0.47
    elif token == '</tool_call>':
        value = -0.20
    elif token == '</tool_response>':
        value = 0.14
    elif n == 2 and previous == 'Title' and token == ':':
        value = 10.54
    else:
        value = 0.0
    return state, value

"""A spelling detector for consonant-heavy, unfamiliar word fragments.

Keep the current transliterated word. A short token leaving a consonant
cluster at its end gets a positive value; familiar English words and long
pieces get less. Common digraphs count as one consonant. Capitalized rare
fragments ending in consonant+s get an extra boost. There is also a small
first-position and incomplete-byte-token correction. This approximates
spelling, not full phonology.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text)

@lru_cache(maxsize=50000)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = prefix.token_strings[-1]
    token = spelling(text)
    if not token or not token[0].isalpha():
        previous = ''
    word = re.search('[A-Za-z]*$', previous + token)[0][-40:]
    low = word.lower()
    letters = ''.join(c for c in token.lower() if 'a' <= c <= 'z')
    consonants = re.findall('[^aeiouy]+', letters)
    ending = re.search('[^aeiouy]*$', low)[0]
    coda = re.sub('ch|sh|th|ph|gh|ng|ck', 'X', ending)
    sonorant = len(ending) >= 2 and any(c in 'rlnm' for c in ending[:-1])
    freq = frequency(word)
    has_vowel = bool(re.search('[aeiouy]', low))

    if len(coda) < 2:
        if first:
            ratio = sum(c not in 'aeiouy' for c in letters) / (len(letters) or 1)
            if ratio <= 0.55:
                value = 0.08 if freq <= 3.875 else 0.28
            else:
                value = 0.34 if text.startswith(' ') else 0.62
        elif '\ufffd' in text:
            value = -0.03 if text.startswith(' ') else 0.19
        elif sonorant:
            value = 0.34 if len(word) <= 4 else 0.075
        elif len(consonants) >= 3:
            value = -0.06 if max(map(len, consonants)) == 1 else -0.03
        else:
            value = -0.008
    elif not has_vowel:
        value = -0.08 if text.strip().isupper() and freq > 1.875 else 0.06
    elif len(letters) <= 4:
        if freq <= 3.125:
            if len(word) <= 6:
                value = 0.90 if word.istitle() else 0.60
                if word.istitle() and low.endswith('s'):
                    value = 1.44
            else:
                value = 0.47 if len(letters) <= 3 else 0.27
        elif freq <= 4.375:
            value = 0.41
        elif freq <= 5.125:
            value = 0.23
        else:
            value = 0.06
    elif freq <= 3.125:
        value = 0.20 if len(word) <= 6 else 0.06
    else:
        value = 0.02
    return (doc, word), value

programs.haiku:
"""Unfinished words: pieces of a word that the tokenizer split into several tokens.

Layer 1's MLP output direction for this component promotes word-continuation pieces,
so it reads as a "this word is not finished yet" signal. It fires on a short,
lowercase, consonant-heavy piece that continues a word with no space in front of it,
the kind of piece a name or foreign word is spelled out in: "V|ats|a", "N|ars|armij",
"O|ms|k", "Lav|s". It is strongest when the word began with a capital letter or two
("V", "Ku", "N"), and when the piece ends in "s". Pieces that look like English
digraphs ("ch", "th", "sh", "ph") and vowel-heavy pieces (ordinary English endings such
as "er", "ing", "tion") stay near zero.

Smaller parts: a word-initial stem with one vowel and a consonant cluster (" cons",
" inv") gets a weak value, the replacement character that marks half of a character
split across tokens gets a moderate one, and the first token of each document in a
packed row fires (the row's first token gets a smaller value, since its document may
have started earlier).
"""
READS = ()
VOWELS = set("aeiouyаеёиоуыэюяäöüéèàáíóúåæøœı")


def _first_piece(prefix, t):
    """The first piece of the word that token t continues (walks back over the word)."""
    k = t
    while k > 0 and prefix.document_ids[k - 1] == prefix.document_ids[t]:
        piece, before = prefix.token_strings[k], prefix.token_strings[k - 1]
        if not (piece[:1].isalpha() and before[-1:].isalpha()):
            break
        k -= 1
    return prefix.token_strings[k].strip()


def _has_consonant_cluster(s):
    """True if two consonants stand side by side, as in 'ms', 'rs', 'ld'."""
    return any(a not in VOWELS and b not in VOWELS for a, b in zip(s, s[1:]))


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[-1]
    if t == 0:
        return None, 0.2  # a row can begin inside a document
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.55  # first token of a new document
    if cur == "�":
        return None, 0.2  # half of a character split across tokens
    prev = prefix.token_strings[-2]
    if not (cur.isalpha() and prev[-1:].isalpha()):
        # not inside a word: a word-initial stem such as " cons" or " inv" gets a weak value
        stem = cur[1:]
        is_stem = cur.startswith(" ") and stem.islower() and 3 <= len(stem) <= 4
        if is_stem and _has_consonant_cluster(stem) and sum(c in VOWELS for c in stem) <= 1:
            return None, 0.08
        return None, 0.0
    first = _first_piece(prefix, t)
    capital = first[:1].isupper()
    short_first = len(first) <= 2
    if len(cur) == 1:
        return None, 0.27 if capital else (0.03 if short_first else 0.13)
    if not cur.islower() or not _has_consonant_cluster(cur):
        return None, 0.0
    if len(cur) == 4:
        return None, 0.2
    if len(cur) <= 3:
        if cur.endswith("h"):
            return None, 0.15  # English digraphs: "ch", "th", "sh", "ph"
        if cur.endswith("s"):
            return None, 1.3 if (capital and short_first) else 0.6
        return None, 0.65 if (capital and short_first) else 0.44
    return None, 0.0

programs.sol:
"""A local echo of zero and the letter/sound 'o'.

Zero is most negative when another zero occurred two token pieces ago,
particularly across a decimal point or comma.  Letter echoes are strongest
for short continuations of short words whose preceding piece begins with
an o or consonant-o.  Transliteration applies the same spelling rules across
scripts.  These are approximate averages, not a semantic word detector.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def spelling(text):
    return anyascii(text).lower()


def zero_echo(h):
    p, q, r = h[-1], h[-2], h[-3]
    if q == '0':
        if p.isdigit():
            return -1.54 if p == '0' else -0.45
        if p == '.':
            return -4.60
        if p == ',':
            return -4.04
        return -2.85 if len(p) <= 1 else -1.46
    if r == '0':
        if p.isspace():
            return -2.62
        return -1.79 if p == '0' else -0.19
    if p == '0':
        return -0.36
    if not p:
        return 1.06
    return 0.04 if p.isdigit() else -0.15


def trailing_word(text):
    return re.split('[^a-z]', text)[-1]


def letter_echo(s, h):
    previous = trailing_word(h[-1])
    word = trailing_word(''.join(h))
    previous_o = previous.find('o')
    short_word = len(word) <= 3
    # An o early in the preceding piece, followed by a short continuation.
    if 0 <= previous_o <= 1:
        if len(s) <= 2:
            if short_word:
                if not s[:1].isalpha():
                    return -0.26
                return -2.99 if previous_o == 0 else -2.28
            return -1.33 if len(h[-1]) <= 3 else -0.60
        if s.startswith('o'):
            if len(s) > 3:
                return -0.53
            if not short_word:
                return -0.87
            return -0.32 if previous.endswith('o') else -2.36
        if not s[:1].isalpha():
            return -0.03
        if len(s) > 3:
            return -0.11
        if len(word) > 4:
            return -0.27
        return -2.10 if previous.endswith('o') else -0.71
    # Weaker echoes from farther back, or two o's within one short piece.
    if s.count('o') > 1:
        return -0.79 if len(s) <= 3 else -0.06
    if 'o' in word:
        if s.startswith('o'):
            return -0.91 if len(word) <= 5 else -0.22
        return -0.01
    return 0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = [''] * 5 if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    s = spelling(raw)
    if raw == '0':
        value = zero_echo(h)
    elif 'o' in s:
        value = letter_echo(s, h)
    else:
        value = 0.0035
    return (doc, (h + [s])[-5:]), value

programs.haiku:
"""Candidate K: a digit zero judged by the zeros just before it (0.0, 0,0, 00,
0.00), with weak negatives on a space- or punctuation-led zero and on short
mid-word pieces that contain the letter o."""
READS = ()

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position

    def tok(k):
        q = t - k
        if q < 0 or docs[q] != docs[t]:
            return '^'
        return toks[q]

    cur = toks[t]
    if cur != '0':
        if (cur and not cur.startswith(' ') and cur.isalpha() and len(cur) <= 2
                and ('o' in cur or 'о' in cur)):
            return carry, -0.4     # short word piece with an o
        return carry, 0.0
    p1, p2 = tok(1), tok(2)
    if p1 == '.' and p2 == '0':
        v = -4.6                   # the 0 of "0.0"
    elif p1 == ',' and p2 == '0':
        v = -3.8                   # the 0 of "0,0"
    elif p1 == '0' and p2 in ('.', ','):
        v = -1.5                   # the 0 of "0.00"
    elif p1 == '0' and p2 == '0':
        v = -1.5                   # the 0 of "000"
    elif p1 == '0' and not p2.isdigit():
        v = -1.5                   # a 0 right after a lone 0 and a letter or symbol
    elif p1 in (':', ','):
        v = -0.3
    elif p1 == ' ':
        v = -0.6
    else:
        v = 0.0                    # 10, 1.0, 2024 ...: zeros after a nonzero digit
    return carry, v

programs.sol:
"""A sparse lexical approximation of several independent responses.

`Challenge Level` is strongly positive.  Word-like `ce`, an e/i spelling
split (especially e + ich/ic), and ceiling/wall/writing-board spellings
are negative. Chinese wall and jade bì characters share a negative rule.
Everything else is left near zero. These are separate
observed responses, not a claim that they form one semantic category.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    tail = carry[2] if same_document else b''
    recent_bytes = tail + prefix.token_bytes[-1]
    p = previous.lower()
    word = token.strip().lower()
    value = 0.0

    # The French demonstrative; initial capitalization follows punctuation.
    if token == ' ce':
        value = -3.1
    elif token in (' Ce', 'Ce') and previous and not p[-1:].isalnum():
        value = -2.8
    elif token == 'ce':
        if previous.endswith('\n'):
            value = -3.5
        elif previous and not previous[-1].isalnum():
            value = -2.0
        else:
            value = -0.2

    # Within-word e+i, strongest for the German -eich- spelling.
    if p.endswith('e') and token.startswith('i'):
        if token.startswith('ich'):
            value = -4.0 / (1 + 0.6 * max(0, len(token) - 3))
        elif token.startswith(('ic', 'ik')):
            value = -3.0 / (1 + max(0, len(token) - 3) / 2)
        elif token.startswith(('ib', 'ig', 'ih', 'iv', 'iz')):
            value = -0.3
        if token.startswith('iv') and p.endswith('ce'):
            value = -2.7
    elif p.endswith('c') and token.lower() in ('ic', 'ik', 'ich'):
        value = -2.3

    # Interior surfaces, including the two usual colors of writing boards.
    if word in ('ceiling', 'ceilings') or token == '天花板':
        value = -4.3
    elif token == 'iling' and p.endswith('ce'):
        value = -9.0
    elif word in ('board', 'boards') and p.strip() in ('white', 'black'):
        value = -6.5
    elif token == '板' and previous in ('白', '黑'):
        value = -9.0
    elif token in ('壁', '벽'):
        value = -4.8
    elif token in ('碧', '璧'):
        value = -4.0
    elif token in ('墙', '牆'):
        value = -1.6
    elif word in ('wall', 'walls'):
        value = -0.3

    # A wall/jade character may finish in a separate UTF-8 byte token.
    if '\ufffd' in token:
        for character in '壁벽碧璧':
            if recent_bytes.endswith(character.encode('utf-8')):
                value = -9.5

    if p.strip() == 'challenge' and token == ' Level':
        value = 20.0
    return (doc, token, recent_bytes[-8:]), value

"""Detect short fragments ending in i, especially I in abbreviations.

A terminal I inside a short capital-letter word has the strongest negative
response. Ordinary i-ending fragments are weaker, especially after several
other vowels or in long words. Separate I/i and longer, vowel-rich words are quiet.
Tracks a trailing word and a short non-whitespace run for path detection.
Both are reset at document boundaries. Token-specific variation is omitted.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
I_KANA = frozenset('いぃきぎしじちぢにひびぴみりイィキギシジチヂニヒビピミリ')
GREEK_LETTERS = frozenset(('pi', 'phi', 'chi', 'psi', 'xi'))

@lru_cache(maxsize=4096)
def english_frequency(word):
    return zipf_frequency(word, 'en')


def response(token, before, in_path=False):
    m = re.search(r'[^\W\d_]+\Z', token)
    if not m:
        return 0.0
    tail = m[0]
    continued = token == tail and bool(before)
    word = before + tail if continued else tail
    # A capital suffix in a camel-case identifier can itself be an abbreviation.
    capitals = re.search(r'[A-Z]+\Z', word)
    abbreviation = capitals[0] if capitals else ''
    if any(c.isupper() and ord(c) > 127 for c in word):
        abbreviation = word if word.isupper() else ''
    if abbreviation and not word.isupper():
        stem = word[:-len(abbreviation)]
        if english_frequency(stem) < 3.0:
            abbreviation = ''
    if tail.endswith('Is'):
        if continued and before.isupper() and len(before) <= 4:
            return -4.8
        return 0.0
    last = tail[-1]
    if last in I_KANA:
        if tail in ('ディ', 'ティ', 'フィ'):
            return -0.75
        if len(tail) == 1 and 'KATAKANA' in unicodedata.name(last):
            return -0.3
        return -0.06
    if last in 'иИіІ':
        if word.isupper() and 1 < len(word) <= 4:
            return -2.0
        if len(tail) == 1 and continued and word.istitle() and len(word) <= 5:
            return -0.65
        return -0.07
    if last == 'ι':
        return -0.18
    if 'LATIN' in unicodedata.name(last, ''):
        last = unicodedata.normalize('NFD', last)[0]
    if last not in 'iI':
        return 0.0
    if last == 'I':
        if token.startswith('.') and before.isupper():
            return -2.0
        if re.fullmatch(r'X{0,3}(IX|IV|V?I{0,3})', word):
            return -0.1
        if token.startswith('.'):
            return -1.5
        if len(tail) > 1 and tail[-2] in 'AEIOU':
            return -0.5
        if continued and len(abbreviation) > len(tail):
            n = len(abbreviation)
            if n == 2:
                return -1.5
            if n == 3:
                return -4.5
            if n == 4:
                return -2.7
            return -1.4 if n == 5 else -0.3
        if len(tail) == 1:
            return -0.5 if continued else -0.07
        if tail.isupper():
            if len(tail) == 2:
                return -0.6
            frequency = english_frequency(tail)
            if frequency < 3.2 and not any(c in 'AEOU' for c in tail[:-1]):
                return -3.0
            return -max(0.2, 4.6 - frequency)
        return -0.1
    low = ''.join(c for c in unicodedata.normalize('NFD', word.lower())
                  if not unicodedata.combining(c))
    vowels = sum(c in 'aeouy' for c in low)
    if (vowels == 0 and len(word) == 3 and low.endswith('si')
            and low not in GREEK_LETTERS):
        return -5.0
    if (in_path and 3 <= len(word) <= 6 and len(tail) <= 4
            and english_frequency(low) < 3.5):
        return -1.5
    if token.startswith('.') and len(tail) <= 3:
        return -1.0
    if vowels == 0 and 3 <= len(word) <= 5 and low not in GREEK_LETTERS:
        return -0.65
    if len(word) >= 9 or vowels >= 2:
        return 0.0
    if len(tail) == 1:
        if not continued:
            return -0.19
        return -1.2 if word.istitle() else -0.55
    if len(tail) > 5:
        return -0.06
    if continued:
        return -0.85 if word.istitle() else -0.23
    return -0.45 if tail.istitle() else -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    run = carry[2] if carry and carry[0] == doc else ''
    run = (run + token)[-120:]
    run = re.split(r'\s', run)[-1]
    value = response(token, before, '/' in run)
    m = re.search(r'[^\W\d_]+\Z', before + token)
    word = m[0][-64:] if m else ''
    return (doc, word, run), value

programs.haiku:
"""Layer 1 MLP down_proj component 5370: a 'clause-initial subject pronoun' detector.

It goes strongly negative on a subject pronoun that opens a clause: "It", "He", "They",
"She" after a full stop, and the same pronouns after a comma, "and", "but", "so".
Its possessive forms (It's "Its", "His", "Their") behave alike at sentence start. I/we/you
are weaker. Subordinators ("that", "if", "when") give a small negative. Object pronouns after
prepositions and verbs ("to it", "make it") stay at zero. Sentence-initial determiners
("The", "This", "There") are mildly negative.

The program reads only the previous token and the current one.
"""
READS = ()

THIRD_PERSON = {"he", "she", "it", "they", "il", "elle", "er", "sie", "es", "el", "ella",
                "他", "她", "它", "他们", "她们", "其"}
POSSESSIVE = {"his", "her", "its", "their"}
FIRST_SECOND = {"i", "we", "you"}
DETERMINERS = {"the", "this", "these", "there", "our", "my", "your", "some"}

SENTENCE_END = {"", ".", "!", "?", "\n", '"', "”", ")", "。", "！", "？"}
CLAUSE_PUNCT = {",", ";", ":", ',"', ",”"}
CONJUNCTIONS = {"and", "but", "so", "then", "or", "yet"}
SUBORDINATORS = {"that", "if", "when", "as", "because", "where", "which", "what", "since",
                 "while", "though", "before", "after", "until", "how", "whether", "who",
                 "although", "unless"}

# Activation when the pronoun follows each kind of word (the table's columns).
TABLE = {
    "third": {"start": -3.3, "punct": -2.1, "conj": -1.5, "sub": -0.6, "other": -0.3},
    "poss": {"start": -2.8, "punct": -0.9, "conj": -0.6, "sub": -0.6, "other": -0.1},
    "first": {"start": -1.1, "punct": -0.6, "conj": -0.5, "sub": -0.1, "other": -0.05},
    "det": {"start": -0.6, "punct": 0.0, "conj": 0.0, "sub": 0.0, "other": 0.0},
}


def _group(word):
    if word in THIRD_PERSON:
        return "third"
    if word in POSSESSIVE:
        return "poss"
    if word in FIRST_SECOND:
        return "first"
    if word in DETERMINERS:
        return "det"
    return None


def _context(prev):
    p = prev.strip()
    if p in SENTENCE_END:
        return "start"
    if p in CLAUSE_PUNCT:
        return "punct"
    if p.lower() in CONJUNCTIONS:
        return "conj"
    if p.lower() in SUBORDINATORS:
        return "sub"
    return "other"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    group = _group(word)
    if group is None:
        return None, 0.0
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = "" if new_doc else prefix.token_strings[-2]
    if group == "det" and not (new_doc or prev.strip() in SENTENCE_END):
        return None, 0.0
    return None, TABLE[group][_context(prev)]

programs.sol:
"""Spelling continuations after C/K/Q, and three-digit numeral windows.

Continuations of short C/K/Q-initial words tend to be positive. An English
frequency table weakens familiar completions; dot/underscore continuations
get a smaller response. Repeated C/K/Q beginnings and periods
after C/Q initials or a line's '4' label tend to be negative. Numerals
respond most strongly when the digit two places back is 4.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# C/K/Q spellings, Czech Č, and Cyrillic К.
INITIALS = 'ckqčк'


@lru_cache(maxsize=30000)
def common_word(word):
    return zipf_frequency(word.lower(), 'en') > 2.75


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        word, number, previous, line = '', '', '', ''
    else:
        _, word, number, previous, line = carry
    token = prefix.token_strings[-1]
    initial = token.strip()[:1].lower()
    value = 0.0
    if first and initial.isalpha():
        value = -0.83 if initial in INITIALS else 0.23

    old_number = number
    if token.isascii() and token.isdigit():
        number += token
        if len(number) >= 3:
            hundreds = number[-3]
            if hundreds == '4':
                value = 0.35 if '4' in number[-2:] else 1.15
            elif hundreds == '8':
                value = 0.27
            elif hundreds == '9':
                value = 0.15
            else:
                value = -0.02 if hundreds == '1' else 0.04
    else:
        number = ''

    if word and word[0].lower() in INITIALS:
        if initial and initial in INITIALS:
            value -= 0.24 if token.strip()[:1].isupper() else 0.10
        elif token[:1].isalpha():
            n = len(word)
            if n == 1:
                value += 0.12
            elif (common_word(word + token)
                  and not word.lower().startswith('ca')):
                value += 0.10
            else:
                value += 0.35 if n <= 6 else 0.14
        elif token[:1] in ('.', '_') and token[1:2].isalpha():
            value += -0.15 if token[1].lower() in INITIALS else 0.20
        elif token.startswith(' ') and len(token.strip()) > 3:
            value += 0.05

    if token in ('.', '．'):
        preceding = previous.strip().lower()
        if preceding in ('c', 'q'):
            value -= 1.6 if line.strip().lower() == preceding else 0.65
        elif old_number == '4' and line.strip() == '4':
            value -= 1.1

    line = (line + token).split('\n')[-1][-80:]
    tail = re.search(r'[^\W\d_]+$', token)
    if tail:
        word = word + token if token.isalpha() else tail.group()
    else:
        word = ''
    return (doc, word[-60:], number[-12:], token, line), float(value)

"""A spelling-level approximation of short y/j-glide and suffix responses.

Short aj/ay/ай-like fragments, and j or Cyrillic y-vowels following
another vowel, give the largest predictions. Common inflectional endings
give smaller predictions. A glide's response leaves a small tail on the
next piece of the same word. Arabic doubling, katakana ya, and repeated
middle dots are separate, weaker spelling cases. Other tokens predict zero.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWEL_EQUIVALENTS = str.maketrans("аеоу", "aeou")
GLIDE_FRAGMENT = re.compile(
    r"[bcdfghjklmnpqrstvwxz]{0,2}([aeou])([jy])[a-z]{0,2}"
)
SUFFIXES = {
    "s": .32, "es": .02, "ed": .19, "ing": .19,
    "er": .08, "ly": .17, "ness": .35,
}
CYRILLIC_ENDINGS = {
    "а", "у", "ы", "и", "ов", "ам", "ом", "ах", "ами",
    "ый", "ое", "ые", "ого", "ому", "ую",
}

@lru_cache(maxsize=100000)
def spelling(token):
    body = token.strip().lower()
    latin = bool(body) and all(
        unicodedata.name(c, "").startswith("LATIN") for c in body
    )
    plain = unicodedata.normalize("NFD", body) if latin else body
    if latin:
        plain = "".join(c for c in plain if not unicodedata.combining(c))
    frequency = zipf_frequency(body, "en") if latin else 0.0
    return body, plain, frequency

def base_response(token, prev):
    body, plain, frequency = spelling(token)
    last = prev[-1:].lower()
    vowel = unicodedata.normalize("NFD", last)[:1]
    vowel = vowel.translate(VOWEL_EQUIVALENTS)
    inside = bool(prev[-1:].isalpha() and token[:1].isalpha())
    initial_capital = len(prev.strip()) == 1 and prev.strip().isupper()
    if len(token) >= 2 and set(token) == {"·"}:
        return 1.54, False
    if body == "ّ":
        return .47, False
    if body == "ヤ":
        return .6, True

    # The glide starts in this short piece, after a vowel in the previous one.
    cyrillic_y_vowel = body[:1] in {"е", "ё", "ю", "я", "є", "ї"}
    if inside and len(body) <= 3:
        if body.startswith("j"):
            if last != unicodedata.normalize("NFD", last)[:1]:
                if unicodedata.name(last, "").startswith("LATIN"):
                    return 1.7, True
            if vowel in "iy" and vowel:
                return -.3, False
            values = ({"a": 2.8, "e": 1.35, "o": 1.4, "u": .58}
                      if body == "j" else
                      {"a": 1.2, "e": .4, "o": .8, "u": .25})
        elif body.startswith("y"):
            values = {"a": .4, "e": .1, "o": .65, "u": .1}
        elif cyrillic_y_vowel:
            values = {"a": 1.6, "e": .55, "o": 1.2, "u": .55}
        elif body.startswith(("ia", "io", "iu")):
            values = {"a": 1.1}
        else:
            values = {}
        if vowel in values and not prev.strip().isupper():
            return values[vowel], True
    if cyrillic_y_vowel and len(body) <= 3 and token[:1].isalpha():
        if last in {"'", "’", "ʼ"}:
            return 1.1, True

    # The glide is spelled within the token, rather than across its boundary.
    if len(body) <= 5:
        if "й" in body:
            if body == "й":
                return .78, True
            if body == "ай":
                return (4.8 if initial_capital else 3.44), True
            if "ай" in body and len(body) <= 3:
                return 2.1, True
            if len(body) <= 2:
                # Back-vowel + й is stronger after liquids/bilabial stops,
                # weaker after nasal consonants. Capitals mark word onsets.
                if body == "ой":
                    if initial_capital:
                        return 1.8, True
                    if last in {"м", "н"}:
                        return .1, True
                    if last in {"р", "л", "б", "п"}:
                        return 1.25, True
                    return .65, True
                return (1.5 if initial_capital else .27), True
        match = GLIDE_FRAGMENT.fullmatch(plain) if frequency < 4 else None
        if match:
            if len(plain) == 2:
                if plain == "ay" and inside and vowel in "aeiou" and vowel:
                    return -.43, False
                value = (1.92 if match[2] == "j" else .71)
                if initial_capital:
                    value = 3.0 if match[2] == "j" else 1.2
                return (value if match[1] == "a" else
                        (.60 if match[2] == "j" else 0.0)), True
            value = (1.12 if match[2] == "j" else .49)
            return (value if match[1] == "a" else
                    (.24 if match[2] == "j" else 0.0)), True

    if inside:
        if body in SUFFIXES:
            if body == "s" and prev.strip().isupper():
                return .65, False
            if body == "es" and prev.lower().endswith(("s", "x", "z", "ch", "sh")):
                return .62, False
            return SUFFIXES[body], False
        if len(body) > 1 and body[0] == last and body[1:] in {"ed", "ing"}:
            return .43, False
        if body == "ая":
            return .72, False
        if body in CYRILLIC_ENDINGS:
            return .15, False
    return 0.0, False

def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    prev, tail = carry[1:] if carry and carry[0] == doc else ("", 0.0)
    value, glide = base_response(token, prev)
    inside = bool(prev[-1:].isalpha() and token[:1].isalpha())
    prediction = value + (.19 * tail if inside else 0.0)
    return (doc, token, max(value, 0.0) if glide else 0.0), prediction

"""Positive for tel-like spelling fragments, especially Russian -тель/-тел-.

Matches can span two tokens. The next unspaced Cyrillic token gets a
continuation response. Word frequencies weaken Russian matches whose bare
-тел spelling is more common than the noun-like -тель spelling. Some Latin
-tel/-ciel spellings are positive; editor and -tor fragments are negative.
Separate rules cover document-initial Title: and opening digits 12/122.
Unmatched tokens get zero, and state resets at document boundaries.
"""
import re
from wordfreq import zipf_frequency

READS = ()
RUSSIAN = re.compile(r'[а-яё]+\Z')
EL_ENDING = re.compile(r'ел[ьяеюи]?\Z')
EDITOR = re.compile(r'[ ./_-]*editors?\Z')
TOR_ENDING = re.compile(r'(?:(?:a|i|u|ul|in)tors?|atory|atorial|itory)\Z')


def fragment(s, previous, word):
    """Return (activation, starts a Russian-inflection echo), or no match."""
    if s.startswith(('ател', 'ител', 'ятел', 'тель')):
        if s.endswith('тель'):
            return 6.1, True
        if s.endswith('тел'):
            return 8.5, True
        return (3.55 if 'тельн' in s else 4.5), True
    if EL_ENDING.fullmatch(s) and previous.endswith('т'):
        if s in ('ел', 'ели'):
            stem = word[:-len(s)]
            soft_form = zipf_frequency(stem + 'ель', 'ru')
            bare_form = zipf_frequency(stem + 'ел', 'ru')
            if bare_form > max(2.0, soft_form + 0.5):
                return (0.9 if s == 'ел' else 2.9), True
        long_stem = len(previous.strip()) > 4
        if s == 'ел':
            return (3.3 if long_stem else 10.4), True
        if s == 'ель':
            return (3.35 if long_stem else 8.2), True
        return (2.3 if long_stem else 6.0), True
    if s == 'тел' and previous.endswith(('а', 'и', 'я')):
        return 8.5, True
    if s == 'аль' and previous.endswith('т'):
        return 3.1, False
    if re.fullmatch('[aiy]tel', s):
        return 3.5, False
    if (re.fullmatch('el[slni]?', s)
            and previous.endswith(('t', 'ť', 'ţ', 'ț', 'т'))):
        if previous.endswith('tt'):
            return 0.2, False
        vowel = len(previous) > 1 and previous[-2] in 'aiyáí'
        return (3.9 if vowel else 0.7), False
    if (re.fullmatch(r'l(?:e[msn]?|i)?|ľ', s)
            and previous.endswith(('te', 'té', 'cie'))):
        slavic = previous.endswith(('ate', 'ite', 'icie'))
        return (3.5 if slavic else 0.8), False
    if s == 'iel' and previous.endswith('c'):
        return (6.8 if previous.endswith('yc') else 0.55), False
    if s in ('tel', 'otel'):
        return 0.45, False
    if s == 'itle':
        return 1.3, False
    if EDITOR.fullmatch(s):
        if s.startswith('_'):
            return -0.57, False
        return (-5.3 if s.startswith('-') else -2.05), False
    if TOR_ENDING.fullmatch(s):
        return -0.39, False
    return None


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word, echo, position, beginning = '', '', False, 0, token
    else:
        _, previous, word, echo, position, beginning = carry
    s = token.lower()
    word = re.split(r'[^а-яё]', word + s)[-1][-64:]
    match = fragment(s, previous.lower(), word)
    value, next_echo = match if match is not None else (0.0, False)
    if match is None and echo and RUSSIAN.fullmatch(s):
        value = 3.8 if s == 'но' else 2.0
    if position == 1 and beginning == 'Title' and token == ':':
        value = 4.825
    if beginning == '1' and token == '2':
        if position == 1:
            value = 3.954
        elif position == 2 and previous == '2':
            value = 1.433
    return (doc, token, word, next_echo, position + 1, beginning), value
